        !period ||
        !Number.isInteger(period.remainingDays) ||
        period.remainingDays < 0 ||
        period.remainingDays > 366 ||
        !['active', 'ended'].includes(period.status) ||
        (period.status === 'active') !== period.remainingDays > 0
