function createSettingsPages(state, actions) {
  function settingsSectionVisible(selector) {
    const element = typeof selector === 'string' ? actions.$(selector) : selector;
    return (
      state.currentView === 'settings' &&
      state.sessionReady !== false &&
      !document.hidden &&
      Boolean(element?.isConnected) &&
      !element.closest('[hidden], details:not([open]), dialog:not([open])')
    );
  }
  function sizeSettingsPage() {
    const panel = actions.$('.settings-panel.settings-pages');
    if (!panel || state.currentView !== 'settings') return;
    const landscape = document.body.classList.contains('phone-landscape');
    const height = window.visualViewport?.height || window.innerHeight;
    const nav = document.querySelector('.topbar .app-nav'),
      bar = document.querySelector('.topbar'),
      fixed =
        nav && window.getComputedStyle(nav).position === 'fixed'
          ? nav
          : bar && window.getComputedStyle(bar).position === 'fixed'
            ? bar
            : null;
    const bounds = fixed?.getBoundingClientRect();
    const bottom = fixed && bounds.top > height / 2 ? Math.max(0, height - bounds.top) : 0;
    const workspace = landscape && panel.closest('.workspace');
    const workspaceBottom = workspace
      ? workspace.getBoundingClientRect().bottom -
        (parseFloat(window.getComputedStyle(workspace).paddingBottom) || 0)
      : height;
    const available = landscape
      ? Math.min(height + (window.visualViewport?.offsetTop || 0), workspaceBottom) -
        panel.getBoundingClientRect().top
      : height - panel.getBoundingClientRect().top - bottom - 16;
    panel.style.setProperty(
      '--settings-space',
      `${Math.max(landscape ? 0 : 220, Math.floor(available))}px`,
    );
    const tiles = panel.querySelector('.settings-tiles');
    if (!landscape && tiles && window.matchMedia('(min-width: 981px)').matches) {
      // The page is anchored to the panel, outside the independently scrolling menu.
      panel.style.setProperty('--settings-desktop-top', `${tiles.offsetTop}px`);
      panel.style.setProperty(
        '--settings-desktop-bottom',
        `${Math.max(0, panel.clientHeight - tiles.offsetTop - tiles.offsetHeight)}px`,
      );
    } else {
      panel.style.removeProperty('--settings-desktop-top');
      panel.style.removeProperty('--settings-desktop-bottom');
    }
  }
  function syncSettingsPage(block = null) {
    const panel = actions.$('.settings-panel');
    const tiles = panel?.querySelector('.settings-tiles');
    if (!tiles) return;
    if (block?.open)
      for (const other of tiles.children)
        if (other !== block && other.matches('details.settings-tile[open]')) other.open = false;
    if (!panel.classList.contains('settings-pages')) return;
    const active = tiles.querySelector(':scope > details.settings-tile[open]');
    if (active) {
      panel.dataset.settingsOpen = active.querySelector('.settings-accordion-content')?.id || '';
      tiles.dataset.settingsOpen = panel.dataset.settingsOpen;
    } else {
      delete panel.dataset.settingsOpen;
      delete tiles.dataset.settingsOpen;
    }
    sizeSettingsPage();
  }
  function mountSettingsPages() {
    const panel = actions.$('.settings-panel.settings-pages');
    if (!panel) return;
    if (
      !document.body.classList.contains('phone-landscape') &&
      window.matchMedia('(min-width: 980px)').matches
    ) {
      const first = panel.querySelector('.settings-tiles > details.settings-tile');
      if (first) first.open = true;
    }
    syncSettingsPage();
  }
  function bindSettingsPageEvents() {
    const root = actions.$('#global-view');
    root.addEventListener(
      'toggle',
      (event) => {
        const block = event.target;
        if (!block.matches('.settings-tiles > details.settings-tile')) return;
        syncSettingsPage(block);
        if (block.open) {
          block.querySelector('.settings-page-title')?.focus({ preventScroll: true });
          void actions.syncVisibleTelegram({ force: true });
        }
      },
      true,
    );
    root.addEventListener('click', (event) => {
      const back = event.target.closest('[data-settings-back]');
      if (!back || state.busy) return;
      const block = back.closest('details.settings-tile');
      if (!block) return;
      block.open = false;
      syncSettingsPage();
      block.querySelector(':scope > summary')?.focus({ preventScroll: true });
    });
    window.addEventListener('resize', sizeSettingsPage);
    window.visualViewport?.addEventListener('resize', sizeSettingsPage);
    document.addEventListener('phone-layout-change', sizeSettingsPage);
  }
  return { mountSettingsPages, bindSettingsPageEvents, settingsSectionVisible };
}

function createProfileOverview(state, actions) {
  const drafts = new window.WeakMap();
  const fields = (form) => [...form.querySelectorAll('input[name]')];
  const values = (form) => JSON.stringify(fields(form).map((field) => [field.name, field.value]));
  function showProfile(root, editing = root.dataset.profileEditing === 'true') {
    root.dataset.profileEditing = String(editing);
    const editor = editing || window.matchMedia('(min-width: 980px)').matches;
    root.querySelector('[data-profile-editor]').hidden = !editor;
    root.querySelector('[data-profile-overview]').hidden = editor;
  }
  function profileOverviewHtml(result) {
    const { account, organization: org, specialty = '', canEditOrganization } = result;
    const row = (title, value) =>
      `<div class="profile-overview-row"><dt>${actions.esc(title)}</dt><dd>${actions.esc(value || 'Не указано')}</dd></div>`;
    return [
      '<div class="profile-overview-identity">',
      `<span class="profile-overview-avatar" aria-hidden="true">${actions.esc(actions.initials(account.displayName))}</span>`,
      `<div><strong>${actions.esc(account.displayName)}</strong><span>${actions.esc(state.roleNames[actions.accountRole()] || actions.accountRole())}</span></div></div>`,
      '<h4 class="profile-group-heading">Ваш аккаунт</h4>',
      '<dl class="profile-overview-list">',
      row('Почта для входа', account.email),
      row('Специальность', specialty),
      ...(org
        ? [
            '</dl><h4 class="profile-group-heading">Для клиентов</h4><dl class="profile-overview-list">',
            row('Название для клиентов', org.name),
            row('Город', org.city),
            row('Телефон организации', org.phone),
            ...(result.canEditContactPhone
              ? [row('Ваш телефон для клиентов', result.contactPhone)]
              : []),
          ]
        : []),
      '</dl><div class="profile-overview-actions"><button type="button" class="primary" data-profile-edit>Редактировать профиль</button></div>',
      org && !canEditOrganization
        ? '<p class="form-hint">Сведения организации изменяет владелец.</p>'
        : '',
      '<p data-profile-result role="status" aria-live="polite"></p>',
    ].join('');
  }
  function syncProfileOverview(result, form) {
    const root = form.closest('#profile-settings');
    if (!root) return;
    root.querySelector('[data-profile-overview]').innerHTML = profileOverviewHtml(result);
    const data = {
      displayName: result.account.displayName,
      specialty: result.specialty || '',
      expectedSpecialty: result.specialty || '',
      organizationName: result.organization?.name || '',
      city: result.organization?.city || '',
      phone: result.organization?.phone || '',
      contactPhone: result.contactPhone || '',
      expectedContactPhone: result.contactPhone || '',
    };
    for (const field of fields(form))
      if (Object.hasOwn(data, field.name)) field.value = data[field.name];
    drafts.set(form, {
      baseline: values(form),
      fields: fields(form).map((field) => [field.name, field.value]),
    });
    const editing = !root.querySelector('[data-profile-editor]').hidden;
    showProfile(root, false);
    if (editing) {
      root.querySelector('[data-profile-result]').textContent = 'Профиль сохранён';
      if (root.querySelector('[data-profile-editor]').hidden)
        root.querySelector('[data-profile-edit]')?.focus({ preventScroll: true });
    }
    actions.markSettingsSaved(form);
  }
  function bindProfileOverviewEvents() {
    document.addEventListener('click', async (event) => {
      const button = event.target.closest('[data-profile-edit], [data-profile-cancel]');
      if (!button || state.busy) return;
      const root = button.closest('#profile-settings');
      const form = root?.querySelector('#account-profile-form');
      if (!form) return;
      const expectedAccount = state.account;
      const draft = drafts.get(form);
      if (button.hasAttribute('data-profile-cancel')) {
        if (
          draft &&
          values(form) !== draft.baseline &&
          !(await actions.confirmAction(
            'Отменить изменения профиля?',
            'Введённые сведения не будут сохранены.',
            'Отменить изменения',
            'Продолжить редактирование',
          ))
        )
          return;
        if (state.busy || state.account !== expectedAccount || !root.isConnected) return;
        for (const [name, value] of draft?.fields || []) form.elements[name].value = value;
        actions.markSettingsSaved(form);
        showProfile(root, false);
        if (root.querySelector('[data-profile-editor]').hidden)
          root.querySelector('[data-profile-edit]')?.focus({ preventScroll: true });
      } else {
        showProfile(root, true);
        root.querySelector('[data-profile-result]').textContent = '';
        form.elements.displayName.focus({ preventScroll: true });
      }
    });
    window.matchMedia('(min-width: 980px)').addEventListener('change', () => {
      const root = actions.$('#profile-settings');
      if (root?.querySelector('[data-profile-editor]')) showProfile(root);
    });
  }
  return { profileOverviewHtml, syncProfileOverview, bindProfileOverviewEvents };
}

function createOrganizationTimeZoneSettings(state, actions) {
  async function mountOrganizationTimeZone() {
    const root = actions.$('#organization-time-zone-settings');
    if (!root) return;
    const account = state.account;
    try {
      const result = await actions.request('/api/cabinet/time-zone');
      if (!root.isConnected || state.account !== account) return;
      root.innerHTML =
        '<details class="organization-time-zone-panel"><summary>Часовой пояс<span data-zone-current></span></summary><form id="organization-time-zone-form" class="organization-time-zone-form">' +
        '<label class="field" for="telegram-time-zone">Часовой пояс всей организации</label>' +
        actions.timeZoneSelect(result.timeZone) +
        '<p class="form-hint">Единое время календаря, онлайн-записи и напоминаний на всех устройствах.</p>' +
        '<button type="submit" class="secondary">Сохранить часовой пояс</button><p role="status" data-zone-message></p></form></details>';
      root.querySelector('form').dataset.timeZone = result.timeZone;
      root.querySelector('[data-zone-current]').textContent =
        root.querySelector('select').selectedOptions[0]?.textContent || result.timeZone;
      root.querySelector('details').open = window.matchMedia('(min-width: 980px)').matches;
    } catch (error) {
      if (root.isConnected) root.textContent = error.message;
    }
  }
  function bindOrganizationTimeZoneEvents() {
    window.matchMedia('(min-width: 980px)').addEventListener('change', (event) => {
      const panel = actions.$('#organization-time-zone-settings .organization-time-zone-panel');
      if (panel) panel.open = event.matches;
    });
    document.addEventListener('submit', async (event) => {
      if (event.target.id !== 'organization-time-zone-form') return;
      event.preventDefault();
      const form = event.target,
        account = state.account,
        message = form.querySelector('[data-zone-message]');
      const timeZone = form.elements.timeZone.value,
        expectedTimeZone = form.dataset.timeZone;
      if (state.busy || timeZone === expectedTimeZone || !timeZone) return;
      if (
        !(await actions.confirmAction(
          'Изменить часовой пояс организации?',
          'Указанные часы записей останутся прежними, но их фактическое время и время рассылки изменятся. Потребуется заново подтвердить записи. Изменение действует для всех сотрудников.',
          'Изменить часовой пояс',
        ))
      )
        return;
      if (state.busy || state.account !== account || !form.isConnected) return;
      state.busy = true;
      const button = form.querySelector('button'),
        select = form.elements.timeZone;
      button.disabled = true;
      select.disabled = true;
      try {
        const result = await actions.request('/api/cabinet/time-zone', {
          method: 'POST',
          body: JSON.stringify({ timeZone, expectedTimeZone }),
        });
        if (state.account !== account || !form.isConnected) return;
        actions.applyCabinetTimeZone(result.timeZone);
        select.value = result.timeZone;
        form.closest('details').querySelector('[data-zone-current]').textContent =
          select.selectedOptions[0]?.textContent || result.timeZone;
        form.dataset.timeZone = result.timeZone;
        actions.markSettingsSaved(form);
        message.textContent = 'Часовой пояс сохранён';
      } catch (error) {
        if (form.isConnected)
          message.textContent = error.outcomeUnknown
            ? 'Результат неизвестен. Перед повторным сохранением обновите настройки и проверьте часовой пояс.'
            : error.message;
      } finally {
        state.busy = false;
        if (button.isConnected) button.disabled = false;
        if (select.isConnected) select.disabled = false;
      }
    });
  }
  return { mountOrganizationTimeZone, bindOrganizationTimeZoneEvents };
}

function createStaffNotificationActions(state, actions) {
  async function changeStaffNotification(channel, action, ui) {
    const { root, key, current, render, syncChannel, validInvitation } = ui;
    if (!current() || channel.busy || state.busy || !channel.snapshot) return;
    const expectedKey = key,
      before = channel.snapshot,
      enabled = root.querySelector(`[data-${channel.prefix}-toggle]`)?.checked,
      events = channel.draftEvents ||
        before.events || ['new-request', 'client-agreed', 'client-declined'];
    if (action === 'unlink' || action === 'toggle') {
      channel.busy = true;
      render();
      let accepted = false;
      try {
        accepted = await actions.confirmAction(
          action === 'unlink'
            ? `Отключить мой ${channel.name}?`
            : `${enabled ? 'Включить' : 'Выключить'} мои уведомления ${channel.name}?`,
          'Изменится только ваше подключение. Клиентские напоминания и другой сервис не изменятся. Неотправленные сообщения при отключении будут отменены.',
          action === 'unlink' ? 'Отключить' : 'Подтвердить',
        );
      } catch {
        if (current() && key === expectedKey)
          channel.message = 'Не удалось подтвердить действие. Попробуйте ещё раз.';
      } finally {
        channel.busy = false;
      }
      if (
        !accepted ||
        !current() ||
        key !== expectedKey ||
        state.busy ||
        channel.snapshot !== before
      ) {
        render();
        return;
      }
    }
    channel.generation++;
    channel.busy = true;
    channel.message = '';
    render();
    try {
      const route =
        action === 'connect'
          ? 'link'
          : action === 'unlink'
            ? 'unlink'
            : action === 'test'
              ? 'test'
              : 'settings';
      const result = await actions.request(`/api/${channel.id}/staff/${route}`, {
        method: 'POST',
        body: JSON.stringify(
          action === 'connect'
            ? {}
            : {
                bindingId: before.bindingId,
                ...(action === 'toggle' ? { enabled } : action === 'events' ? { events } : {}),
              },
        ),
      });
      if (!current() || key !== expectedKey) return;
      if (action === 'connect') {
        if (!validInvitation(channel, result))
          throw Error('Не удалось получить безопасную личную ссылку. Повторите подключение.');
        channel.invitation = result;
      } else if (action === 'test') {
        channel.message = 'Пробное сообщение поставлено в очередь. Проверьте ' + channel.name + '.';
      } else if (channel.snapshot?.bindingId === before.bindingId) {
        channel.snapshot = { ...channel.snapshot, ...result };
        if (action === 'events' || action === 'unlink') channel.draftEvents = null;
      }
    } catch (error) {
      if (current() && key === expectedKey) channel.message = error.message;
    } finally {
      channel.busy = false;
      if (current() && key === expectedKey) {
        render();
        if (!channel.message) {
          if (channel.loading) channel.refreshQueued = true;
          else await syncChannel(channel);
        }
      }
    }
  }
  return { changeStaffNotification };
}

function createStaffNotifications(state, actions) {
  let root = null,
    key = '',
    pushCheckedAt = -Infinity;
  const scope = () => JSON.stringify([state.account?.id, state.account?.organizationId]);
  const current = () => root?.isConnected && key === scope() && state.currentView === 'settings';
  const channels = [
    { id: 'telegram', name: 'Telegram', prefix: 'staff-notify' },
    { id: 'max', name: 'MAX', prefix: 'staff-max' },
  ].map((channel) => ({
    ...channel,
    snapshot: null,
    invitation: null,
    loading: false,
    busy: false,
    message: '',
    checkedAt: -Infinity,
    retryAt: 0,
    generation: 0,
    refreshQueued: false,
    draftEvents: null,
  }));
  function validInvitation(channel, value) {
    try {
      const url = new URL(value.url);
      return (
        Number.isSafeInteger(value.expiresAt) &&
        value.expiresAt > Date.now() &&
        url.protocol === 'https:' &&
        !url.username &&
        !url.password &&
        !url.port &&
        !url.hash &&
        [...url.searchParams.keys()].length === 1 &&
        /^staff_[A-Za-z0-9_-]{43}$/.test(url.searchParams.get('start') || '') &&
        (channel.id === 'telegram'
          ? url.hostname === 't.me' && /^\/[A-Za-z0-9_]{5,32}$/.test(url.pathname)
          : url.hostname === 'max.ru' && url.pathname === '/id000000000000_1_bot')
      );
    } catch {
      return false;
    }
  }
  const eventItems = [
    ['new-request', 'Новая заявка онлайн-записи'],
    ['client-agreed', 'Клиент согласовал время'],
    ['client-declined', 'Клиент отказался от времени'],
    ['created', 'Создана запись'],
    ['moved', 'Запись перенесена'],
    ['cancelled', 'Запись отменена'],
    ['confirmation', 'Запись подтверждена'],
    ['completed', 'Приём завершён'],
    ['no_show', 'Отмечена неявка'],
    ['restored', 'Запись восстановлена'],
    ['removed', 'Запись удалена'],
    ['updated', 'Другие изменения записи'],
  ];
  function eventPreferences(channel, disabled) {
    const events = channel.snapshot.events || eventItems.slice(0, 3).map(([id]) => id);
    return (
      '<form data-' +
      channel.prefix +
      '-events data-staff-binding="' +
      actions.esc(channel.snapshot.bindingId || '') +
      '"><fieldset ' +
      (disabled ? 'disabled' : '') +
      '><legend>Какие уведомления получать</legend><div class="staff-push-events">' +
      eventItems
        .map(
          ([id, label]) =>
            '<label><input type="checkbox" name="event" value="' +
            id +
            '" ' +
            (events.includes(id) ? 'checked' : '') +
            '><span>' +
            label +
            '</span></label>',
        )
        .join('') +
      '</div><button type="submit" class="primary">Сохранить</button>' +
      '<button type="button" class="secondary" data-' +
      channel.prefix +
      '-test>Проверить уведомления</button></fieldset></form>'
    );
  }
  function renderChannel(channel) {
    const { snapshot, prefix, busy, name } = channel,
      esc = actions.esc;
    if (channel.invitation && !validInvitation(channel, channel.invitation))
      channel.invitation = null;
    const invitation = channel.invitation,
      linked = snapshot?.linked,
      ready = snapshot?.available && snapshot?.bot?.connected;
    const stateText = !snapshot
      ? channel.message
        ? 'Не удалось проверить'
        : 'Проверяем…'
      : channel.id === 'max' && !snapshot.prepared
        ? 'Пока недоступен'
        : linked
          ? snapshot.compatible === false
            ? 'Переподключите'
            : snapshot.enabled
              ? ready
                ? snapshot.events?.length === 0
                  ? 'События не выбраны'
                  : 'Включены'
                : 'Подключён · сервис недоступен'
              : 'Подключён · выключены'
          : ready
            ? 'Не подключён'
            : 'Сервис недоступен';
    const body = [
      `<p class="staff-channel-intro">Выберите уведомления для ${name}.</p>`,
      linked
        ? `<div class="telegram-switch"><input id="staff-${channel.id}-enabled" type="checkbox" aria-label="Получать уведомления в ${name}" data-${prefix}-toggle ${snapshot.enabled ? 'checked' : ''} ${busy || !ready || snapshot.compatible === false ? 'disabled' : ''}><span>Получать уведомления</span></div>`
        : '',
      snapshot?.compatible === false
        ? '<p class="form-hint">Чтобы получать уведомления, отключите старое подключение и подключите канал заново.</p>'
        : '',
      !linked && invitation
        ? [
            '<div class="staff-notification-actions">',
            `<a class="primary staff-telegram-open" href="${esc(invitation.url)}" target="_blank" rel="noopener noreferrer">Открыть ${name}</a>`,
            `<button type="button" class="secondary" data-${prefix}-copy>Копировать ссылку</button>`,
            '</div><details class="staff-notification-link"><summary>Личная ссылка · 15 минут</summary>',
            `<input readonly aria-label="Личная ссылка ${name}" value="${esc(invitation.url)}"></details>`,
            `<p class="form-hint">Откройте ${name} по кнопке и запустите уведомления. Личная ссылка действует 15 минут.</p>`,
          ].join('')
        : '',
      !linked && !invitation && (ready || busy)
        ? `<button type="button" class="primary" data-${prefix}-connect ${busy || !ready ? 'disabled' : ''}>Подключить ${name}</button>`
        : '',
      snapshot && !ready
        ? '<p class="staff-channel-unavailable">Подключение сейчас недоступно. Можно проверить доступность позже.</p>'
        : '',
      linked && snapshot.compatible !== false ? eventPreferences(channel, busy || !ready) : '',
      linked
        ? `<button type="button" class="text-btn booking-danger" data-${prefix}-unlink ${busy ? 'disabled' : ''}>Отключить ${name}</button>`
        : '',
      `<button type="button" class="text-btn staff-channel-refresh" data-${prefix}-refresh ${busy ? 'disabled' : ''}>Обновить статус</button>`,
    ].join('');
    return {
      id: channel.id,
      name,
      status: stateText,
      linked: linked && ready && snapshot.compatible !== false && snapshot.enabled,
      loading: !snapshot && !channel.message,
      body,
      message: channel.message,
    };
  }
  function render() {
    if (!current()) return;
    if (!root.querySelector('.staff-notification-channels'))
      root.innerHTML =
        '<div class="staff-notification-heading"><div class="settings-label-row"><h3 id="telegram-staff-heading">Мои уведомления</h3>' +
        actions.settingsHelpHtml(
          'Личные уведомления сотрудников',
          `${actions.canManageTeam() ? 'События заявок и записей всей организации' : 'События ваших заявок и записей'} в Telegram и MAX. Каждый сотрудник подключает себя самостоятельно. Пуши настраиваются отдельно на каждом устройстве.\n\nЭто не подключение клиентов и не настройка их напоминаний. Телефоны, история и фотографии в сообщения не включаются.`,
        ) +
        '</div><p class="staff-notification-account">' +
        actions.esc(state.account?.displayName || 'Мой аккаунт') +
        ' · ' +
        actions.esc(
          state.roleNames[state.account?.role] ||
            state.roleNames[state.teamAccess?.actorRole] ||
            'Мой аккаунт',
        ) +
        '</p></div><div class="staff-notification-channels">' +
        [...channels]
          .reverse()
          .map((channel) => `<div data-staff-slot="${channel.id}"></div>`)
          .join('') +
        '<div id="staff-push"></div></div>';
    for (const channel of channels) {
      const slot = root.querySelector(`[data-staff-slot="${channel.id}"]`);
      const changed = actions.renderStaffChannelPanel(slot, renderChannel(channel));
      const form = slot.querySelector('[data-' + channel.prefix + '-events]');
      if (form && changed) {
        actions.markSettingsSaved(form);
        if (channel.draftEvents)
          for (const field of form.querySelectorAll('[name="event"]'))
            field.checked = channel.draftEvents.includes(field.value);
      }
    }
    if (actions.settingsSectionVisible(root)) actions.mountStaffPush?.({ refresh: false });
  }
  async function syncChannel(channel, { force = true } = {}) {
    if (
      !current() ||
      !actions.settingsSectionVisible(root) ||
      channel.loading ||
      channel.busy ||
      state.busy
    )
      return;
    const interval =
      channel.invitation && validInvitation(channel, channel.invitation) ? 4000 : 30000;
    if (!force && Date.now() < Math.max(channel.checkedAt + interval, channel.retryAt)) return;
    const expectedRoot = root,
      expectedKey = key,
      operation = ++channel.generation;
    channel.loading = true;
    try {
      const result = await actions.readBackground(`/api/${channel.id}/staff`);
      if (
        !current() ||
        root !== expectedRoot ||
        key !== expectedKey ||
        operation !== channel.generation
      )
        return;
      const changed = JSON.stringify(channel.snapshot) !== JSON.stringify(result);
      const expired = channel.invitation && !validInvitation(channel, channel.invitation);
      if (channel.snapshot?.bindingId !== result.bindingId) channel.draftEvents = null;
      channel.snapshot = result;
      channel.retryAt = 0;
      if (result.linked) channel.invitation = null;
      if (changed || expired || channel.message) {
        channel.message = '';
        render();
      }
    } catch (error) {
      if (
        current() &&
        root === expectedRoot &&
        key === expectedKey &&
        operation === channel.generation
      ) {
        channel.retryAt = Date.now() + 30000;
        channel.message = error.message;
        render();
      }
    } finally {
      channel.loading = false;
      if (current() && key === expectedKey && operation === channel.generation)
        channel.checkedAt = Date.now();
      if (current() && (root !== expectedRoot || key !== expectedKey || channel.refreshQueued)) {
        channel.refreshQueued = false;
        void syncChannel(channel);
      }
    }
  }
  async function syncStaffNotifications({ force = true } = {}) {
    if (!current() || !actions.settingsSectionVisible(root)) return;
    render();
    await Promise.all(channels.map((channel) => syncChannel(channel, { force })));
    if (
      current() &&
      actions.settingsSectionVisible(root) &&
      (force || Date.now() - pushCheckedAt >= 30000)
    ) {
      pushCheckedAt = Date.now();
      await actions.syncStaffPush?.();
    }
  }
  function change(channel, action) {
    const expectedRoot = root,
      expectedKey = key;
    return actions.changeStaffNotification(channel, action, {
      root,
      key,
      render,
      syncChannel,
      validInvitation,
      current: () => current() && root === expectedRoot && key === expectedKey,
    });
  }
  function mountStaffNotifications() {
    const nextRoot = actions.$('#staff-notifications'),
      nextKey = scope();
    if (nextRoot && nextRoot === root && nextKey === key) return;
    const sameScope = nextKey === key;
    root = nextRoot;
    key = nextKey;
    if (!sameScope)
      for (const channel of channels) {
        channel.snapshot = null;
        channel.invitation = null;
        channel.message = '';
        channel.draftEvents = null;
        channel.checkedAt = -Infinity;
        channel.retryAt = 0;
        channel.generation++;
        channel.refreshQueued = false;
      }
    if (!sameScope) pushCheckedAt = -Infinity;
    if (!root) return;
    render();
    root.addEventListener('click', async (event) => {
      for (const channel of channels) {
        if (event.target.closest(`[data-staff-channel-open="${channel.id}"]`))
          void syncChannel(channel);
        if (event.target.closest(`[data-${channel.prefix}-refresh]`)) void syncChannel(channel);
        if (event.target.closest(`[data-${channel.prefix}-connect]`))
          void change(channel, 'connect');
        if (event.target.closest(`[data-${channel.prefix}-unlink]`)) void change(channel, 'unlink');
        if (event.target.closest(`[data-${channel.prefix}-test]`)) void change(channel, 'test');
        if (
          event.target.closest(`[data-${channel.prefix}-copy]`) &&
          current() &&
          channel.invitation
        ) {
          const expectedKey = key,
            invitation = channel.invitation;
          try {
            await navigator.clipboard.writeText(invitation.url);
            if (current() && key === expectedKey && channel.invitation === invitation) {
              channel.message = 'Ссылка скопирована';
              render();
            }
          } catch {
            if (!current() || key !== expectedKey || channel.invitation !== invitation) return;
            const section = root.querySelector(`[data-staff-channel="${channel.id}"]`),
              field = section.querySelector('.staff-notification-link input');
            field.closest('details').open = true;
            field.focus();
            field.select();
            section.querySelector('.telegram-settings-result').textContent =
              'Ссылка выделена — скопируйте её вручную.';
          }
        }
      }
    });
    root.addEventListener('change', (event) => {
      for (const channel of channels) {
        if (event.target.matches('[data-' + channel.prefix + '-toggle]'))
          void change(channel, 'toggle');
        const form = event.target.closest('[data-' + channel.prefix + '-events]');
        if (form)
          channel.draftEvents = [...form.querySelectorAll('[name="event"]:checked')].map(
            (field) => field.value,
          );
      }
    });
    root.addEventListener('submit', (event) => {
      for (const channel of channels)
        if (event.target.matches('[data-' + channel.prefix + '-events]')) {
          event.preventDefault();
          channel.draftEvents = [...event.target.querySelectorAll('[name="event"]:checked')].map(
            (field) => field.value,
          );
          void change(channel, 'events');
        }
    });
  }
  return { mountStaffNotifications, syncStaffNotifications };
}

function createBookingPublication(state, actions) {
  let synchronize = () => {};
  function syncBookingPublication(value) {
    synchronize(value);
  }
  const scope = () => JSON.stringify([state.account?.id, state.account?.organizationId]);
  function mountBookingPublication(snapshot) {
    const root = actions.$('#booking-publication');
    if (!root || !snapshot.publication?.canManage) return;
    const key = scope();
    let publication = snapshot.publication,
      pending = false;
    const live = () => root.isConnected && key === scope() && state.currentView === 'settings';
    function path() {
      const staff = root.querySelector('[data-booking-link-staff]')?.value;
      const staffPath = staff && publication.staffPaths?.[staff];
      const url = new URL(staffPath || publication.path, location.origin);
      if (staff && !staffPath) url.searchParams.set('staff', staff);
      return url.href;
    }
    function render() {
      const settings = root.parentElement?.querySelector('#online-booking-settings-form');
      if (settings) settings.hidden = !publication.enabled;
      const esc = actions.esc;
      const members = snapshot.members.filter(
        (m) =>
          (snapshot.staff[m.accountId]?.enabled ?? m.role !== 'salon_admin') &&
          (publication.staffPaths == null || Object.hasOwn(publication.staffPaths, m.accountId)),
      );
      root.innerHTML = [
        '<form id="booking-publication-form" class="booking-publication">',
        '<div class="settings-label-row"><label class="checkbox-hit-area"><input type="checkbox" name="enabled" aria-labelledby="booking-publication-label" ',
        publication.enabled ? 'checked' : '',
        '></label><span id="booking-publication-label">Включить публичную онлайн-запись</span>',
        actions.settingsHelpHtml(
          'Публичная онлайн-запись',
          'Клиенты увидят услуги, специалистов и доступное время. Чужие записи и данные клиентов не показываются. Публичную ссылку можно отправить клиентам или разместить в профиле организации; QR-код ведёт на ту же страницу.',
        ),
        '</div>',
        publication.enabled
          ? [
              members.length > 1
                ? '<label class="field">Ссылка для<select data-booking-link-staff><option value="">Всей организации</option>' +
                  members
                    .map(
                      (m) => `<option value="${esc(m.accountId)}">${esc(m.displayName)}</option>`,
                    )
                    .join('') +
                  '</select></label>'
                : '',
              '<label class="field">Публичная ссылка<input data-booking-public-link readonly></label>',
              '<div class="booking-link-actions"><button type="button" class="secondary" data-booking-link-action="open">Открыть страницу</button><button type="button" class="secondary" data-booking-link-action="share">Отправить ссылку</button>',
              '<button type="button" class="secondary" data-booking-link-action="copy">Копировать</button><button type="button" class="secondary" data-booking-link-action="qr">QR-код</button></div>',
              '<img data-booking-public-qr width="220" height="220" alt="QR-код онлайн-записи" hidden>',
            ].join('')
          : '',
        publication.disabledReason === 'no_working_days'
          ? `<p>${
              publication.hasWorkingDays
                ? 'График настроен. Включите онлайн-запись вручную.'
                : 'Онлайн-запись выключена: нет открытых рабочих дней. Настройте рабочее время.'
            }</p>`
          : '',
        '<p data-booking-publication-result role="status"></p></form>',
      ].join('');
      const field = root.querySelector('[data-booking-public-link]');
      if (field) field.value = path();
    }
    root.addEventListener('change', async (event) => {
      if (event.target.matches('input[name="enabled"]')) {
        const checkbox = event.target,
          enabled = checkbox.checked;
        checkbox.checked = publication.enabled;
        if (!live() || state.busy || pending || enabled === publication.enabled) return;
        pending = true;
        try {
          const accepted = await actions.confirmAction(
            enabled ? 'Включить онлайн-запись?' : 'Выключить онлайн-запись?',
            enabled
              ? 'Клиенты смогут записываться по публичной ссылке. Будет действовать сохранённый вид онлайн-записи.'
              : 'Новые записи по публичной ссылке будут недоступны. Существующие записи и заявки сохранятся.',
            enabled ? 'Включить запись' : 'Выключить запись',
          );
          if (accepted && live() && !state.busy) await savePublication(enabled);
        } finally {
          pending = false;
        }
      }
      if (event.target.matches('[data-booking-link-staff]') && live()) {
        root.querySelector('[data-booking-public-link]').value = path();
        const image = root.querySelector('[data-booking-public-qr]');
        image.hidden = true;
        image.removeAttribute('src');
      }
    });
    root.addEventListener('submit', (event) => event.preventDefault());
    async function savePublication(enabled) {
      state.busy = true;
      root.querySelector('input[name="enabled"]').disabled = true;
      try {
        const result = await actions.request('/api/online-booking/publication', {
          method: 'POST',
          body: JSON.stringify({
            enabled,
            revision: publication.revision,
          }),
        });
        if (!live()) return;
        publication = result;
        render();
        void actions.refreshBookingHealth({ force: true });
        root.querySelector('[data-booking-publication-result]').textContent = result.enabled
          ? 'Публичная запись включена.'
          : result.disabledReason === 'no_working_days'
            ? 'Нет открытых рабочих дней. Настройте график и включите запись вручную.'
            : 'Публичная запись выключена.';
      } catch (error) {
        if (live())
          root.querySelector('[data-booking-publication-result]').textContent = error.message;
      } finally {
        state.busy = false;
        if (live()) root.querySelector('input[name="enabled"]').disabled = false;
      }
    }
    root.addEventListener('click', async (event) => {
      const button = event.target.closest('[data-booking-link-action]');
      if (!button || !live() || state.busy || !publication.enabled) return;
      const value = path(),
        message = root.querySelector('[data-booking-publication-result]');
      try {
        if (button.dataset.bookingLinkAction === 'open') {
          window.open(value, '_blank', 'noopener,noreferrer');
          return;
        }
        if (button.dataset.bookingLinkAction === 'qr') {
          const staff = root.querySelector('[data-booking-link-staff]')?.value || '';
          const result = await actions.request(
            '/api/online-booking/qr?staff=' + encodeURIComponent(staff),
          );
          if (!live() || value !== path()) return;
          const image = root.querySelector('[data-booking-public-qr]');
          image.src = result.dataUrl;
          image.hidden = false;
          return;
        }
        if (button.dataset.bookingLinkAction === 'share' && typeof navigator.share === 'function') {
          await navigator.share({
            title: 'Онлайн-запись',
            text: 'Выберите услуги и удобное время для записи.',
            url: value,
          });
          return;
        }
        if (navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(value);
          if (live()) message.textContent = 'Ссылка скопирована.';
        } else {
          const field = root.querySelector('[data-booking-public-link]');
          field.focus();
          field.select();
          message.textContent = 'Ссылка выделена — скопируйте её.';
        }
      } catch (error) {
        if (live() && error.name !== 'AbortError')
          message.textContent = 'Не удалось отправить автоматически. Скопируйте ссылку из поля.';
      }
    });
    synchronize = (next) => {
      if (
        !live() ||
        !next?.canManage ||
        state.busy ||
        pending ||
        next.revision < publication.revision
      )
        return;
      if (
        ['enabled', 'revision', 'disabledReason', 'hasWorkingDays', 'path'].every(
          (name) => next[name] === publication[name],
        ) &&
        JSON.stringify(next.staffPaths || {}) === JSON.stringify(publication.staffPaths || {})
      )
        return;
      const checkbox = root.querySelector('input[name="enabled"]');
      const dirty = checkbox?.form.dataset.publicationDirty === 'true';
      const draft = checkbox?.checked;
      const focused = document.activeElement === checkbox;
      const staff = root.querySelector('[data-booking-link-staff]')?.value;
      publication = next;
      render();
      const updated = root.querySelector('input[name="enabled"]');
      if (dirty) {
        updated.checked = draft;
        updated.form.dataset.publicationDirty = 'true';
      }
      const select = root.querySelector('[data-booking-link-staff]');
      if (select && [...select.options].some((option) => option.value === staff)) {
        select.value = staff;
        root.querySelector('[data-booking-public-link]').value = path();
      }
      if (focused) updated.focus({ preventScroll: true });
    };
    render();
  }
  return { mountBookingPublication, syncBookingPublication };
}

function createOnlineBookingSettings(state, actions) {
  let snapshot = null,
    snapshotScope = '',
    sequence = 0;
  const scope = () => JSON.stringify([state.account?.id, state.account?.organizationId]);
  const formValues = (form) =>
    JSON.stringify(
      [...form.querySelectorAll('input, select, textarea')].map((field) => [
        field.name,
        field.value,
        field.checked,
      ]),
    );
  const ruleLabels = {
    mode: { any: 'Любое свободное время', sequential: 'Последовательно' },
    bookingMode: { approval: 'С согласованием', classic: 'Сразу в календарь' },
  };
  const staffRule = (id, field) =>
    Object.hasOwn(ruleLabels[field], snapshot.staff[id]?.[field])
      ? snapshot.staff[id][field]
      : 'inherit';
  function staffRuleSelect(id, field, label, attribute) {
    const value = staffRule(id, field);
    return [
      `<label class="booking-member-rule">${label}<select name="${field}:${actions.esc(id)}" ${attribute}="${actions.esc(id)}">`,
      `<option value="inherit" ${value === 'inherit' ? 'selected' : ''}>Как в организации</option>`,
      ...Object.entries(ruleLabels[field]).map(
        ([key, text]) =>
          `<option value="${key}" ${value === key ? 'selected' : ''}>${text}</option>`,
      ),
      '</select></label>',
    ].join('');
  }
  function updateStaffRules(form) {
    if (!form) return;
    const defaults = {
      mode: form.querySelector('#booking-settings-mode').value,
      bookingMode: form.querySelector('#booking-settings-kind').value,
    };
    const inherited = { mode: 0, bookingMode: 0 };
    let hasApproval = defaults.bookingMode === 'approval';
    for (const row of form.querySelectorAll('[data-booking-member]')) {
      const enabled = row.querySelector('[data-booking-enabled]').checked;
      for (const [field, attribute] of [
        ['mode', 'data-booking-staff-mode'],
        ['bookingMode', 'data-booking-staff-kind'],
      ]) {
        const select = row.querySelector(`[${attribute}]`);
        const followsDefault = select.value === 'inherit';
        const effective = followsDefault ? defaults[field] : select.value;
        select.querySelector('[value="inherit"]').textContent =
          'Как в организации — ' + ruleLabels[field][defaults[field]];
        row.querySelector(`[data-booking-effective="${field}"]`).textContent =
          ruleLabels[field][effective] + (followsDefault ? ' (общие правила)' : '');
        if (enabled && followsDefault) inherited[field]++;
        if (enabled && field === 'bookingMode' && effective === 'approval') hasApproval = true;
      }
    }
    const hint = form.querySelector('[data-booking-inheritance]');
    if (hint)
      hint.textContent = `Общие правила для принимающих сотрудников: выбор времени — ${inherited.mode}; оформление — ${inherited.bookingMode}.`;
    const reservation = form.querySelector('[data-booking-reservation-field]');
    if (reservation) reservation.hidden = !hasApproval;
  }
  function leadTimeOptions(current) {
    const periods = [
      15,
      30,
      45,
      60,
      ...Array.from({ length: 23 }, (_, i) => (i + 2) * 60),
      ...Array.from({ length: 6 }, (_, i) => (i + 2) * 1440),
      14 * 1440,
    ];
    if (!periods.includes(current)) periods.push(current);
    return periods
      .sort((a, b) => a - b)
      .map((minutes) => {
        const text =
          minutes === 0
            ? 'Без ограничения'
            : minutes >= 2880 && minutes % 1440 === 0
              ? minutes / 1440 + (minutes / 1440 < 5 ? ' дня' : ' дней')
              : minutes > 60 && minutes % 60 === 0
                ? minutes / 60 + ' ч.'
                : minutes + ' мин.';
        return `<option value="${minutes}" ${minutes === current ? 'selected' : ''}>${text}</option>`;
      })
      .join('');
  }
  function onlineBookingSettingsHtml() {
    snapshot = null;
    snapshotScope = '';
    return actions.settingsSectionHtml(
      'Онлайн-запись',
      'online-booking-settings',
      '<p class="settings-loading">Загрузка настроек…</p>',
    );
  }
  function renderOnlineBookingSettings() {
    const root = actions.$('#online-booking-settings');
    if (!root || !snapshot) return;
    const esc = actions.esc;
    if (!snapshot.canManage) {
      root.innerHTML = `<p>Управление своими заявками: <strong>${snapshot.canManageOwnRequests ? 'разрешено' : 'выключено владельцем или администратором'}</strong>.</p><button type="button" class="secondary" data-management-tab="requests">Открыть заявки</button>`;
      return;
    }
    const enabled = (m) => snapshot.staff[m.accountId]?.enabled ?? m.role !== 'salon_admin';
    const members = snapshot.members
      .filter((m) => ['owner', 'cosmetologist'].includes(m.role))
      .map((m) =>
        [
          `<div class="online-booking-member" data-booking-member="${esc(m.accountId)}"><strong>${esc(m.displayName || 'Имя не заполнено')}</strong>`,
          `<small>${esc(m.specialty || state.roleNames[m.role] || '')}</small>`,
          `<label class="check-field"><input type="checkbox" data-booking-enabled="${esc(m.accountId)}" ${enabled(m) ? 'checked' : ''}>Принимает по онлайн-записи</label>`,
          m.role === 'cosmetologist'
            ? [
                `<label class="check-field"><input type="checkbox" data-booking-permission="${esc(m.accountId)}" `,
                `${snapshot.staff[m.accountId]?.manageOwnRequests !== false ? 'checked' : ''}>Может управлять своими заявками</label>`,
              ].join('')
            : '',
          '<p class="booking-member-effective"><span data-booking-effective="mode"></span><span data-booking-effective="bookingMode"></span></p>',
          '<details class="booking-member-rules"><summary>Настроить</summary><div class="booking-member-rule-fields">',
          staffRuleSelect(m.accountId, 'mode', 'Выбор времени', 'data-booking-staff-mode'),
          staffRuleSelect(m.accountId, 'bookingMode', 'Оформление', 'data-booking-staff-kind'),
          '</div></details>',
          '</div>',
        ].join(''),
      )
      .join('');
    root.innerHTML = [
      '<div class="booking-health-panel" data-booking-health-panel role="status" hidden></div>',
      '<div id="booking-publication"></div>',
      `<form id="online-booking-settings-form" ${snapshot.publication?.enabled ? '' : 'hidden'}><p class="booking-defaults-heading">Общие правила организации</p><div class="online-booking-fields">`,
      '<div class="field"><div class="settings-label-row"><span id="booking-settings-kind-label">Вид онлайн-записи</span>',
      actions.settingsHelpHtml(
        'Вид онлайн-записи',
        'С согласованием: сотрудник принимает заявку. Сразу в календарь: выбранное свободное время сразу записывается, клиент получает подтверждение на сайте. Посещение автоматически не оформляется. Ниже можно задать отдельное правило сотруднику.',
      ),
      `</div><input type="hidden" id="booking-settings-kind" name="bookingMode" value="${snapshot.bookingMode === 'classic' ? 'classic' : 'approval'}">`,
      '<div class="booking-kind-switch" role="group" aria-labelledby="booking-settings-kind-label">',
      `<button type="button" class="secondary" data-booking-kind="approval" aria-pressed="${snapshot.bookingMode !== 'classic'}">С согласованием</button>`,
      `<button type="button" class="secondary" data-booking-kind="classic" aria-pressed="${snapshot.bookingMode === 'classic'}">Сразу в календарь</button></div></div>`,
      '<div class="field"><div class="settings-label-row"><span id="booking-settings-mode-label">Выбор времени</span>',
      actions.settingsHelpHtml(
        'Выбор времени онлайн-записи',
        'Клиентам доступны только открытые рабочие дни. Любое свободное время: все подходящие начала приёма. Последовательно: одно самое раннее подходящее время на выбранный день; после его занятия доступно следующее. Правило можно изменить отдельно для сотрудника. Ручная и голосовая запись этим выбором не ограничены.',
      ),
      `</div><input type="hidden" id="booking-settings-mode" name="mode" value="${snapshot.mode === 'sequential' ? 'sequential' : 'any'}">`,
      '<div class="booking-kind-switch" role="group" aria-labelledby="booking-settings-mode-label">',
      `<button type="button" class="secondary" data-booking-time-mode="any" aria-pressed="${snapshot.mode !== 'sequential'}">Любое свободное время</button>`,
      `<button type="button" class="secondary" data-booking-time-mode="sequential" aria-pressed="${snapshot.mode === 'sequential'}">Последовательно</button></div></div>`,
      '<div class="field"><div class="settings-label-row"><label for="booking-settings-lead">За сколько до начала закрывать запись</label>',
      actions.settingsHelpHtml(
        'Когда закрывать онлайн-запись',
        'Клиент может записаться только заранее, не позднее выбранного срока до начала приёма. Это не время отправки напоминания. Уже созданные записи не меняются.',
      ),
      '</div><select id="booking-settings-lead" name="minimumLeadMinutes" required>',
      leadTimeOptions(snapshot.minimumLeadMinutes),
      '</select><small>Например, 14 дней: клиенту нужно записаться минимум за две недели до приёма.</small></div>',
      `<div class="field" data-booking-reservation-field ${snapshot.bookingMode === 'classic' ? 'hidden' : ''}><div class="settings-label-row"><label for="booking-settings-reservation">На сколько минут бронировать время</label>`,
      actions.settingsHelpHtml(
        'Резерв заявки',
        'Общий срок резерва для сотрудников с оформлением «С согласованием». Запрос другого времени не резервирует слот. При записи сразу в календарь резерв не используется.',
      ),
      '</div><input id="booking-settings-reservation" type="number" name="reservationMinutes" min="1" max="1440" step="1" required ',
      `value="${snapshot.reservationMinutes}"><small>Если заявку не приняли за это время, бронь снимается.</small></div></div>`,
      `<div class="settings-label-row"><label class="check-field booking-price-setting"><input type="checkbox" name="showPrices" ${snapshot.showPrices !== false ? 'checked' : ''}>Показывать стоимость услуг в онлайн-записи</label>`,
      actions.settingsHelpHtml(
        'Стоимость в онлайн-записи',
        'При выключении клиент видит услуги и длительность, но не цены и общую сумму. Стоимость в картотеке сохраняется.',
      ),
      '</div>',
      '<p class="booking-inheritance-hint" data-booking-inheritance></p>',
      '<details class="compact-accordion"><summary>Сотрудники</summary>',
      `<div class="online-booking-members">${members}</div></details>`,
      '<button type="submit" class="primary">Сохранить правила</button>',
      '<p id="booking-settings-result" role="status"></p></form>',
    ].join('');
    updateStaffRules(root.querySelector('#online-booking-settings-form'));
    actions.mountBookingPublication(snapshot);
    actions.renderBookingHealth();
    void actions.refreshBookingHealth();
  }
  async function loadOnlineBookingSettings() {
    if (!state.multiUser || state.currentView !== 'settings') return;
    const key = scope(),
      id = ++sequence;
    try {
      const result = await actions.request('/api/online-booking/settings');
      if (key !== scope() || id !== sequence || state.currentView !== 'settings') return;
      snapshot = result;
      snapshotScope = key;
      renderOnlineBookingSettings();
    } catch (error) {
      if (key === scope() && id === sequence) {
        const root = actions.$('#online-booking-settings');
        if (root) root.textContent = error.message;
      }
    }
  }
  function bindOnlineBookingSettingsEvents() {
    const resetSaveFeedback = (event) => {
      const form = event.target.closest('#online-booking-settings-form');
      if (!form || snapshotScope !== scope()) return;
      const button = form.querySelector('button[type="submit"]');
      if (button.dataset.saveState === 'saved') {
        delete button.dataset.saveState;
        button.textContent = 'Сохранить правила';
        button.disabled = state.busy;
      }
      const result = form.querySelector('#booking-settings-result');
      if (result) result.textContent = '';
    };
    document.addEventListener('input', resetSaveFeedback);
    document.addEventListener('change', resetSaveFeedback);
    document.addEventListener('click', (e) => {
      const button = e.target.closest('[data-booking-kind], [data-booking-time-mode]');
      if (!button || state.busy || !snapshot || snapshotScope !== scope()) return;
      const kind = button.hasAttribute('data-booking-kind');
      const value = kind ? button.dataset.bookingKind : button.dataset.bookingTimeMode;
      const field = button
        .closest('form')
        ?.querySelector(kind ? '#booking-settings-kind' : '#booking-settings-mode');
      if (!field || field.value === value) return;
      field.value = value;
      field.dispatchEvent(new Event('change', { bubbles: true }));
    });
    document.addEventListener('change', (e) => {
      const form = e.target.closest('#online-booking-settings-form');
      if (!form || !snapshot || snapshotScope !== scope()) return;
      if (
        e.target.matches(
          '#booking-settings-mode, #booking-settings-kind, [data-booking-enabled], [data-booking-staff-mode], [data-booking-staff-kind]',
        )
      )
        updateStaffRules(form);
      if (e.target.id === 'booking-settings-mode') {
        for (const button of e.target
          .closest('form')
          ?.querySelectorAll('[data-booking-time-mode]') || [])
          button.setAttribute(
            'aria-pressed',
            String(button.dataset.bookingTimeMode === e.target.value),
          );
        return;
      }
      if (e.target.id === 'booking-settings-kind') {
        for (const button of e.target.closest('form')?.querySelectorAll('[data-booking-kind]') ||
          [])
          button.setAttribute(
            'aria-pressed',
            String(button.dataset.bookingKind === e.target.value),
          );
        return;
      }
    });
    document.addEventListener('submit', async (e) => {
      if (e.target.id !== 'online-booking-settings-form') return;
      e.preventDefault();
      if (!snapshot || state.busy || snapshotScope !== scope()) return;
      const form = e.target,
        key = scope(),
        button = form.querySelector('button[type="submit"]');
      const fields = new FormData(form),
        submittedValues = formValues(form),
        staff = { ...snapshot.staff },
        services = { ...snapshot.services };
      const enabledInputs = new Map(
        [...form.querySelectorAll('[data-booking-enabled]')].map((input) => [
          input.dataset.bookingEnabled,
          input,
        ]),
      );
      const permissionInputs = new Map(
        [...form.querySelectorAll('[data-booking-permission]')].map((input) => [
          input.dataset.bookingPermission,
          input,
        ]),
      );
      const ruleInputs = new Map(
        [...form.querySelectorAll('[data-booking-member]')].map((row) => [
          row.dataset.bookingMember,
          row,
        ]),
      );
      for (const m of snapshot.members) {
        if (!['owner', 'cosmetologist'].includes(m.role)) continue;
        const check = enabledInputs.get(m.accountId);
        const permission = permissionInputs.get(m.accountId);
        const rules = ruleInputs.get(m.accountId);
        if (!check || !rules) continue;
        staff[m.accountId] = {
          ...staff[m.accountId],
          enabled: check.checked,
          manageOwnRequests: permission?.checked ?? staff[m.accountId]?.manageOwnRequests ?? true,
          mode: rules.querySelector('[data-booking-staff-mode]').value,
          bookingMode: rules.querySelector('[data-booking-staff-kind]').value,
        };
      }
      // Old assignment metadata is retained for compatibility; ownership comes from the catalog.
      const catalogIds = new Set(snapshot.catalog.map((service) => service.id));
      for (const id of Object.keys(services)) if (!catalogIds.has(id)) delete services[id];
      state.busy = true;
      button.disabled = true;
      button.textContent = 'Сохраняем…';
      try {
        const saved = await actions.request('/api/online-booking/settings', {
          method: 'POST',
          body: JSON.stringify({
            revision: snapshot.revision,
            mode: fields.get('mode'),
            bookingMode: fields.get('bookingMode'),
            minimumLeadMinutes: Number(fields.get('minimumLeadMinutes')),
            reservationMinutes: Number(fields.get('reservationMinutes')),
            showPrices: fields.get('showPrices') === 'on',
            staff,
            services,
          }),
        });
        if (key !== scope() || !form.isConnected) return;
        // POST returns saved rules; catalog and publication belong to the GET snapshot.
        snapshot = { ...snapshot, ...saved };
        snapshotScope = key;
        const unchanged = formValues(form) === submittedValues;
        if (unchanged) {
          actions.markSettingsSaved(form);
          button.textContent = 'Сохранено';
          button.dataset.saveState = 'saved';
          button.disabled = true;
        }
        void actions.refreshBookingHealth({ force: true });
        const result = actions.$('#booking-settings-result');
        if (result)
          result.textContent = unchanged
            ? 'Правила сохранены'
            : 'Правила сохранены. Новые изменения ещё не сохранены.';
      } catch (error) {
        if (key === scope() && form.isConnected)
          form.querySelector('#booking-settings-result').textContent = error.message;
      } finally {
        state.busy = false;
        if (button.isConnected) {
          button.disabled = button.dataset.saveState === 'saved';
          if (!button.disabled) button.textContent = 'Сохранить правила';
        }
      }
    });
  }
  return {
    onlineBookingSettingsHtml,
    loadOnlineBookingSettings,
    bindOnlineBookingSettingsEvents,
  };
}

function createClientNotificationSettings(state, actions) {
  const scope = () => JSON.stringify([state.account?.id, state.account?.organizationId]);
  const confirming = new WeakSet();
  let sequence = 0;
  async function mountClientNotificationSettings() {
    const root = actions.$('#client-notification-settings'),
      key = scope(),
      id = ++sequence;
    if (!root || confirming.has(root.querySelector('form'))) return;
    try {
      const result = await actions.request('/api/notifications/service-visibility');
      if (!root.isConnected || key !== scope() || id !== sequence) return;
      root.innerHTML = [
        '<form id="client-notification-settings-form" class="client-notification-settings-form">',
        '<div class="settings-label-row">',
        '<label class="checkbox-hit-area"><input type="checkbox" name="showServices" aria-labelledby="client-services-label" ',
        result.showServices ? 'checked' : '',
        '></label><span id="client-services-label">Показывать названия услуг в уведомлениях</span>',
        actions.settingsHelpHtml(
          'Названия услуг в уведомлениях',
          'Общая настройка для Telegram, MAX и будущих сервисов. Названия могут быть видны на экране блокировки. Отказ клиента от показа услуг в подключённом Telegram учитывается и при отправке в MAX. Имя клиента, заметки и фотографии не передаются.',
        ),
        '</div><p role="status" data-notification-message></p>',
        '<button type="button" class="secondary" data-notification-retry hidden>Обновить состояние</button></form>',
      ].join('');
      root.querySelector('form').dataset.showServices = String(result.showServices);
    } catch (error) {
      if (!root.isConnected || key !== scope() || id !== sequence) return;
      root.innerHTML =
        '<p role="alert"></p><button type="button" class="secondary" data-notification-retry>Повторить загрузку</button>';
      root.querySelector('p').textContent = error.message;
    }
  }
  function bindClientNotificationSettingsEvents() {
    document.addEventListener('click', (event) => {
      if (event.target.closest('[data-notification-retry]') && !state.busy)
        void mountClientNotificationSettings();
    });
    // There is no save button; Enter must not submit another settings form.
    document.addEventListener('submit', (event) => {
      if (event.target.id === 'client-notification-settings-form') event.preventDefault();
    });
    document.addEventListener('change', async (event) => {
      const field = event.target;
      if (!field.matches('#client-notification-settings-form input[name="showServices"]')) return;
      const form = field.form,
        key = scope(),
        message = form.querySelector('[data-notification-message]');
      const showServices = field.checked,
        expectedShowServices = form.dataset.showServices === 'true';
      field.checked = expectedShowServices;
      if (
        state.busy ||
        confirming.has(form) ||
        showServices === expectedShowServices ||
        field.disabled
      )
        return;
      confirming.add(form);
      field.disabled = true;
      let saving = false,
        unknown = false;
      try {
        const accepted = await actions.confirmAction(
          showServices ? 'Показывать услуги в уведомлениях?' : 'Скрыть услуги в уведомлениях?',
          showServices
            ? 'Названия услуг появятся в уведомлениях всех подключённых сервисов, включая MAX. Они могут быть видны на экране блокировки.'
            : 'Уведомления продолжат приходить, но без названий услуг. Это действует для всех сервисов.',
          showServices ? 'Показывать услуги' : 'Скрыть услуги',
        );
        if (!accepted || state.busy || !form.isConnected || key !== scope()) return;
        state.busy = true;
        saving = true;
        const result = await actions.request('/api/notifications/service-visibility', {
          method: 'POST',
          body: JSON.stringify({ showServices, expectedShowServices }),
        });
        if (!form.isConnected || key !== scope()) return;
        field.checked = result.showServices;
        form.dataset.showServices = String(result.showServices);
        actions.markSettingsSaved(form);
        message.textContent = 'Настройка уведомлений сохранена';
        form.dispatchEvent(
          new CustomEvent('client-notification-visibility-saved', { bubbles: true }),
        );
      } catch (error) {
        if (!form.isConnected || key !== scope()) return;
        unknown = Boolean(error.outcomeUnknown);
        field.checked = expectedShowServices;
        message.textContent = unknown
          ? 'Результат неизвестен. Обновите состояние перед повторным изменением.'
          : error.message;
        form.querySelector('[data-notification-retry]').hidden = false;
      } finally {
        confirming.delete(form);
        if (saving) state.busy = false;
        if (form.isConnected && key === scope()) {
          field.disabled = unknown;
          if (!unknown) field.focus({ preventScroll: true });
        }
      }
    });
  }
  return { mountClientNotificationSettings, bindClientNotificationSettingsEvents };
}

function createProfile(state, actions) {
  function profileSettingsHtml() {
    return actions.settingsSectionHtml(
      'Мой профиль',
      'profile-settings',
      '<p>Загружаем данные регистрации…</p>',
    );
  }
  function renderProfile(result, root) {
    const {
      account,
      organization: org,
      canEditOrganization,
      canEditContactPhone,
      contactPhone = '',
      specialty = '',
    } = result;
    const esc = actions.esc;
    const organizationFields =
      canEditOrganization && org
        ? [
            '<h4 class="profile-group-heading">Для клиентов</h4>',
            '<label class="field profile-organization-name"><span class="profile-field-label">Название для клиентов</span>',
            `<input name="organizationName" required maxlength="120" value="${esc(org.name)}"></label>`,
            '<label class="field profile-contact-field"><span class="profile-field-label">Город</span>',
            `<input name="city" maxlength="120" autocomplete="address-level2" value="${esc(org.city)}"></label>`,
            '<label class="field profile-contact-field"><span class="profile-field-label">Контактный телефон</span>',
            `<input name="phone" maxlength="40" type="tel" autocomplete="tel" value="${esc(org.phone)}"></label>`,
          ].join('')
        : '';

    root.innerHTML = [
      '<section data-profile-overview>' + actions.profileOverviewHtml(result) + '</section>',
      '<section data-profile-editor hidden aria-label="Редактирование профиля">',
      '<form id="account-profile-form">',
      '<div class="form-grid profile-grid">',
      '<h4 class="profile-group-heading">Ваш аккаунт</h4>',
      '<label class="field profile-display-name"><span class="profile-field-label">Имя и фамилия</span>',
      `<input name="displayName" required maxlength="120" autocomplete="name" value="${esc(account.displayName)}"></label>`,
      '<div class="field"><div class="settings-label-row"><label for="profile-login-email">Почта для входа</label>',
      actions.settingsHelpHtml(
        'Данные профиля',
        'Данные взяты из регистрации. Изменение профиля не меняет пароль и почту для входа.',
      ),
      `</div><input id="profile-login-email" type="email" readonly value="${esc(account.email)}"></div>`,
      org
        ? [
            '<div class="field"><div class="settings-label-row"><label for="profile-specialty">Специальность</label>',
            actions.settingsHelpHtml(
              'Специальность',
              'Необязательное поле. Например: тренер, парикмахер, консультант. Специальность используется в приглашениях и уведомлениях клиентам.',
            ),
            `</div><input id="profile-specialty" name="specialty" maxlength="120" placeholder="Необязательно" value="${esc(specialty)}"></div>`,
            `<input type="hidden" name="expectedSpecialty" value="${esc(specialty)}">`,
          ].join('')
        : '',
      organizationFields,
      canEditContactPhone
        ? '<h4 class="profile-group-heading">Для клиентов</h4><label class="field profile-contact-field"><span class="profile-field-label">Телефон для клиентов</span>' +
          `<input name="contactPhone" maxlength="40" type="tel" autocomplete="tel" value="${esc(contactPhone)}">` +
          '<small class="form-hint">Этот номер может быть показан клиентам на публичной странице онлайн-записи.</small></label>' +
          `<input type="hidden" name="expectedContactPhone" value="${esc(contactPhone)}">`
        : '',
      '</div>',
      org && !canEditOrganization
        ? [
            '<div class="settings-label-row profile-organization-info">',
            `<span>Организация: ${esc(org.name)}</span>`,
            actions.settingsHelpHtml(
              'Сведения организации',
              'Сведения об организации изменяет владелец. Личные поля доступны в вашем профиле.',
            ),
            '</div>',
          ].join('')
        : '',
      '<div class="profile-save-row"><button class="primary" type="submit">Сохранить профиль</button>',
      '<button type="button" class="secondary" data-profile-cancel>Отмена</button>',
      '<p id="profile-message" role="status" aria-live="polite"></p></div>',
      '</form>',
      '</section>',
      org && actions.canManageTeam()
        ? '<section id="organization-time-zone-settings" aria-label="Время организации"><p class="form-hint">Загрузка часового пояса…</p></section>'
        : '',
    ].join('');
    actions.syncProfileOverview(result, root.querySelector('#account-profile-form'));
    void actions.mountOrganizationTimeZone();
  }
  async function loadAccountProfile() {
    const root = actions.$('#profile-settings');
    if (!root || root.querySelector('form')) return;
    const account = state.account;
    try {
      const result = await actions.readBackground('/api/account/profile');
      if (!root.isConnected || state.account !== account) return;
      renderProfile(result, root);
    } catch (e) {
      if (root.isConnected && state.account === account)
        root.innerHTML =
          '<p class="error" role="status">' +
          actions.esc(e.message) +
          '</p><button type="button" class="secondary" id="retry-profile">Повторить загрузку</button>';
    }
  }
  function bindProfileEvents() {
    document.addEventListener('click', (e) => {
      if (e.target.closest('#retry-profile')) void actions.loadAccountProfile();
    });
    document.addEventListener('submit', async (e) => {
      if (e.target.id !== 'account-profile-form') return;
      e.preventDefault();
      if (state.busy) return;
      const account = state.account,
        form = e.target,
        button = form.querySelector('button[type="submit"]'),
        message = form.querySelector('#profile-message');
      const f = new FormData(form),
        values = { displayName: f.get('displayName') };
      if (form.elements.specialty) {
        values.specialty = f.get('specialty');
        values.expectedSpecialty = f.get('expectedSpecialty');
      }
      if (form.elements.contactPhone) {
        values.contactPhone = f.get('contactPhone');
        values.expectedContactPhone = f.get('expectedContactPhone');
      }
      if (form.elements.organizationName)
        values.organization = {
          name: f.get('organizationName'),
          city: f.get('city'),
          phone: f.get('phone'),
        };
      state.busy = true;
      button.disabled = true;
      message.textContent = '';
      try {
        const result = await actions.request('/api/account/profile', {
          method: 'POST',
          body: JSON.stringify(values),
        });
        if (state.account !== account || !form.isConnected) return;
        state.account.displayName = result.account.displayName;
        if (form.elements.expectedSpecialty)
          form.elements.expectedSpecialty.value = result.specialty;
        const heading = actions.$('#account-profile-name');
        if (heading)
          heading.textContent =
            result.account.displayName === state.roleNames[actions.accountRole()]
              ? 'Мой аккаунт'
              : result.account.displayName;
        message.textContent = 'Профиль сохранён';
        actions.syncProfileOverview(result, form);
        actions.toast('Профиль сохранён');
        if (state.teamAccess)
          state.teamAccess.members.forEach((m) => {
            if (m.accountId === state.account.id) {
              m.displayName = result.account.displayName;
              m.specialty = result.specialty;
            }
          });
        if (actions.canManageTeam()) await actions.loadTeamAccess();
      } catch (e) {
        if (message.isConnected) message.textContent = e.message;
      } finally {
        state.busy = false;
        if (button.isConnected) button.disabled = false;
      }
    });
  }
  return { profileSettingsHtml, loadAccountProfile, bindProfileEvents };
}

function createStaffBookingRules(state, actions) {
  const confirming = new WeakSet();
  const canEditRules = () => state.workspace.canEditStaffRules ?? state.workspace.canEdit;
  const protectedStaff = (id) =>
    state.workspace.staffRules?.find((rule) => rule.staffId === id)?.preventOverlap ??
    state.workspace.enabled;
  const ruleInputs = (form) =>
    [...form.elements].filter((input) => input.matches('[data-workspace-staff-rule]'));
  const formRules = (form) =>
    ruleInputs(form).map((input) => ({
      staffId: input.dataset.workspaceStaffRule,
      preventOverlap: input.checked,
    }));
  const headingHtml = (title, subtitle) =>
    '<div class="staff-booking-rules-heading"><span class="staff-booking-rules-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 5 3 3 5-5"/></svg></span><div class="staff-booking-rules-title"><h4>' +
    actions.esc(title) +
    '</h4><p class="form-hint">' +
    actions.esc(subtitle) +
    '</p></div>';
  function ruleRow(member) {
    const name = member.displayName || 'Имя не заполнено',
      blocked = protectedStaff(member.accountId);
    return [
      `<div class="staff-booking-rule-row" data-staff-rule-state="${blocked ? 'blocked' : 'allowed'}">`,
      '<div class="staff-booking-rule-person">',
      `<strong>${actions.esc(name)}</strong><small>${actions.esc(state.roleNames[member.role] || member.role)}${member.accountId === actions.accountId() ? ' · вы' : ''}${member.status === 'active' ? '' : ' · доступ приостановлен'}</small></div>`,
      '<div class="staff-booking-rule-choice">',
      `<span data-staff-rule-label>${blocked ? 'Запрещены' : 'Разрешены'}</span>`,
      `<label class="staff-booking-rule-check"><input type="checkbox" name="staff-overlap-${actions.esc(member.accountId)}" data-workspace-staff-rule="${actions.esc(member.accountId)}" aria-label="Запретить одновременные записи к сотруднику: ${actions.esc(name)}" ${blocked ? 'checked' : ''} ${canEditRules() ? '' : 'disabled'}></label></div></div>`,
    ].join('');
  }
  function renderStaffBookingRules({ rebase = false, force = false } = {}) {
    const root = actions.$('#staff-booking-rules');
    if (!root) return;
    const prior = root.querySelector('#staff-booking-rules-form');
    if (!force && prior && (confirming.has(prior) || prior.dataset.unknown === 'true')) return;
    if (!force && prior && JSON.stringify(formRules(prior)) !== prior.dataset.baseline) {
      if (rebase) prior.dataset.revision = String(state.workspace.revision);
      return;
    }
    const slots = actions.$('#team-settings')?.querySelectorAll('[data-team-rule-staff]');
    if (actions.canManageTeam() && slots?.length) {
      const members = state.teamAccess?.members || state.workspace.members;
      root.innerHTML =
        '<form id="staff-booking-rules-form"><p id="staff-booking-rules-message" class="form-hint" role="status"></p><button type="button" class="secondary" data-staff-rules-refresh hidden>Обновить состояние</button></form>';
      for (const slot of slots) {
        const member = members.find((item) => item.accountId === slot.dataset.teamRuleStaff);
        if (!member) {
          slot.innerHTML = '<p class="form-hint">Загружаем правило…</p>';
          continue;
        }
        const blocked = protectedStaff(member.accountId),
          name = member.displayName || 'Имя не заполнено';
        slot.innerHTML = [
          `<div class="staff-booking-rule-row" data-staff-rule-state="${blocked ? 'blocked' : 'allowed'}">`,
          '<div class="staff-booking-rule-person"><strong>Одновременные записи</strong><small>Во всех кабинетах</small></div>',
          '<div class="staff-booking-rule-choice">',
          `<span data-staff-rule-label>${blocked ? 'Запрещены' : 'Разрешены'}</span>`,
          '<label class="staff-booking-rule-check">',
          `<input type="checkbox" name="staff-overlap-${actions.esc(member.accountId)}" form="staff-booking-rules-form" `,
          `data-workspace-staff-rule="${actions.esc(member.accountId)}" data-staff-name="${actions.esc(name)}" `,
          `aria-label="Запретить одновременные записи к сотруднику: ${actions.esc(name)}" `,
          `${blocked ? 'checked' : ''} ${canEditRules() ? '' : 'disabled'}></label></div></div>`,
          '<p class="form-hint member-rule-hint">Правила кабинетов действуют отдельно. Онлайн-запись предлагает только свободное время.</p>',
        ].join('');
      }
      const form = root.querySelector('#staff-booking-rules-form');
      form.dataset.revision = String(state.workspace.revision);
      form.dataset.baseline = JSON.stringify(formRules(form));
      actions.markSettingsSaved(form);
      return;
    }
    if (!actions.canManageTeam()) {
      const blocked = protectedStaff(actions.accountId());
      root.innerHTML = [
        '<section class="staff-booking-rules-card">',
        headingHtml('Мои правила записи', 'Одновременные записи · во всех кабинетах'),
        '</div><div class="staff-booking-rules-list">',
        `<div class="staff-booking-rule-row" data-staff-rule-state="${blocked ? 'blocked' : 'allowed'}">`,
        '<div class="staff-booking-rule-person"><strong>Одновременные записи ко мне</strong></div>',
        `<div class="staff-booking-rule-choice"><span data-staff-rule-label>${blocked ? 'Запрещены' : 'Разрешены'}</span></div></div></div>`,
        '<p class="form-hint">Правило меняет владелец или администратор. Настройки кабинетов действуют независимо.</p></section>',
      ].join('');
      return;
    }
    const w = state.workspace;
    if (!w.members.length) {
      root.innerHTML = '<p class="form-hint">Загружаем правила записи…</p>';
      return;
    }
    root.innerHTML = [
      '<section class="staff-booking-rules-card">',
      headingHtml('Правила записи к сотрудникам', 'Одновременные записи · во всех кабинетах'),
      actions.settingsHelpHtml(
        'Одновременные записи к сотруднику',
        'Галочка запрещает пересекающиеся по времени записи только к указанному сотруднику, во всех кабинетах. Если снять её, при ручной записи эта проверка отключится. Правила остальных сотрудников не изменятся.\n\n' +
          'Запрет пересечений в каждом кабинете действует независимо. Онлайн-запись по-прежнему предлагает только свободное время специалиста.\n\n' +
          'При постановке и снятии галочки запрашивается подтверждение. После подтверждения правило сохраняется сразу. При включении запрета сервер проверит будущие записи; прежние записи не удаляются.',
      ),
      '</div><form id="staff-booking-rules-form">',
      `<div class="staff-booking-rules-list">${w.members
        .filter((member) => ['owner', 'cosmetologist'].includes(member.role))
        .map(ruleRow)
        .join('')}</div>`,
      canEditRules() ? '' : '<p class="form-hint">Правила меняет владелец или администратор.</p>',
      '<p id="staff-booking-rules-message" class="form-hint" role="status"></p><button type="button" class="secondary" data-staff-rules-refresh hidden>Обновить состояние</button></form></section>',
    ].join('');
    const form = root.querySelector('#staff-booking-rules-form');
    form.dataset.revision = String(w.revision);
    form.dataset.baseline = JSON.stringify(formRules(form));
    actions.markSettingsSaved(form);
  }
  function bindStaffBookingRulesEvents() {
    document.addEventListener('submit', (event) => {
      if (event.target.id === 'staff-booking-rules-form') event.preventDefault();
    });
    document.addEventListener('change', async (event) => {
      const input = event.target;
      if (
        !input.matches('[data-workspace-staff-rule]') ||
        input.form?.id !== 'staff-booking-rules-form'
      )
        return;
      const form = input.form,
        staffRules = JSON.parse(form.dataset.baseline),
        rule = staffRules.find((item) => item.staffId === input.dataset.workspaceStaffRule),
        requested = input.checked,
        original = rule.preventOverlap,
        message = form.querySelector('#staff-booking-rules-message'),
        account = state.account;
      input.checked = original;
      if (
        state.busy ||
        !canEditRules() ||
        input.disabled ||
        confirming.has(form) ||
        requested === original
      )
        return;
      const name =
        input.dataset.staffName ||
        input.closest('.staff-booking-rule-row').querySelector('strong').textContent;
      confirming.add(form);
      form.dataset.confirming = 'true';
      input.disabled = true;
      let saving = false,
        unknown = false;
      try {
        const accepted = await actions.confirmAction(
          requested ? 'Запретить одновременные записи?' : 'Разрешить одновременные записи?',
          `${name}: ${requested ? 'записи на пересекающееся время будут запрещены' : 'при ручной записи запрет пересечений будет выключен'} во всех кабинетах. Правила остальных сотрудников и кабинетов не изменятся.`,
          requested ? 'Запретить' : 'Разрешить',
          'Отмена',
        );
        if (!accepted || state.busy || !form.isConnected || state.account !== account) return;
        rule.preventOverlap = requested;
        const values = { revision: Number(form.dataset.revision), staffRules };
        state.busy = true;
        saving = true;
        message.textContent = 'Сохраняем правило…';
        const result = await actions.request('/api/workspace', {
          method: 'POST',
          body: JSON.stringify(values),
        });
        if (state.account !== account) return;
        state.workspace = result;
        state.roomCacheKey = '';
        state.roomBusy = [];
        // The command changes only staff rules; leave an open room draft untouched.
        const roomsForm = actions.$('#workspace-settings-form');
        if (roomsForm) roomsForm.dataset.workspaceRevision = String(result.revision);
        renderStaffBookingRules({ force: true });
        actions.toast('Правила записи к сотрудникам сохранены');
      } catch (error) {
        if (!form.isConnected || state.account !== account) return;
        unknown = Boolean(error.outcomeUnknown || error.status === 409);
        form.dataset.unknown = String(unknown);
        message.textContent = error.outcomeUnknown
          ? 'Результат сохранения неизвестен. Обновите состояние перед следующим изменением.'
          : error.message;
        form.querySelector('[data-staff-rules-refresh]').hidden = false;
        if (error.outcomeUnknown) {
          const row = input.closest('.staff-booking-rule-row');
          row.dataset.staffRuleState = 'unknown';
          row.querySelector('[data-staff-rule-label]').textContent = 'Неизвестно';
        }
      } finally {
        confirming.delete(form);
        delete form.dataset.confirming;
        if (saving) state.busy = false;
        if (form.isConnected && state.account === account) {
          for (const field of ruleInputs(form)) field.disabled = unknown || !canEditRules();
          if (!unknown) input.focus({ preventScroll: true });
        }
      }
    });
    document.addEventListener('click', async (event) => {
      const button = event.target.closest('[data-staff-rules-refresh]');
      if (!button || state.busy) return;
      const form = button.form,
        account = state.account;
      if (confirming.has(form)) return;
      confirming.add(form);
      button.disabled = true;
      try {
        const result = await actions.request('/api/workspace');
        if (!form.isConnected || state.account !== account) return;
        state.workspace = result;
        state.roomCacheKey = '';
        state.roomBusy = [];
        renderStaffBookingRules({ force: true });
      } catch (error) {
        if (form.isConnected)
          form.querySelector('#staff-booking-rules-message').textContent = error.message;
      } finally {
        confirming.delete(form);
        if (button.isConnected) button.disabled = false;
      }
    });
  }
  return { renderStaffBookingRules, bindStaffBookingRulesEvents };
}

function createWorkspaceView(state, actions) {
  const roomIcon =
    '<span class="workspace-room-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 3v18m5-10v2"/></svg></span>';
  const canAssignRooms = () => state.workspace.canEdit || state.workspace.canEditRoomAssignments;
  function workspaceSettingsHtml() {
    return actions.settingsSectionHtml(
      'Кабинеты и занятость',
      'workspace-settings',
      '<p>Загружаем кабинеты…</p>',
    );
  }
  function workspaceRoomEditorHtml(room, index = 0, expanded = false) {
    const specialists = state.workspace.members.filter((member) =>
      ['owner', 'cosmetologist'].includes(member.role),
    );
    const disabled = state.workspace.canEdit ? '' : 'disabled',
      assignmentDisabled = canAssignRooms() ? '' : 'disabled',
      overlapDisabled =
        state.workspace.canEdit || state.workspace.canEditRoomOverlap ? '' : 'disabled',
      multiple = room.staffMode === 'multiple',
      soleAssignedStaff =
        specialists.length === 1 &&
        room.staffIds.length === 1 &&
        room.staffIds[0] === specialists[0].accountId;
    const staff = specialists
      .map((member) =>
        [
          `<label>`,
          `<input type="${multiple ? 'checkbox' : 'radio'}" `,
          `name="staff-${actions.esc(room.id)}" data-room-staff value="${actions.esc(member.accountId)}" ${room.staffIds.includes(member.accountId) ? 'checked' : ''} ${assignmentDisabled}><span class="workspace-staff-person"><strong>${actions.esc(member.displayName || 'Имя не заполнено')}</strong><small>${actions.esc(state.roleNames[member.role] || member.role)}${member.status === 'active' ? '' : ' · доступ приостановлен'}</small></span>`,
          `</label>`,
        ].join(''),
      )
      .join('');
    return [
      `<article class="workspace-room" `,
      `data-room-id="${actions.esc(room.id)}" data-room-expanded="${expanded}">`,
      '<div class="workspace-room-overview"><div>',
      `<strong data-room-summary-name>${actions.esc(room.name)}</strong>`,
      `<small data-room-summary-staff>${actions.esc(
        specialists
          .filter((member) => room.staffIds.includes(member.accountId))
          .map((member) => member.displayName || 'Имя не заполнено')
          .join(', ') || 'Сотрудники не назначены',
      )}${room.active ? '' : ' · Не действует'}</small></div>`,
      `<button type="button" class="text-btn" data-room-edit aria-expanded="${expanded}" aria-controls="room-heading-${actions.esc(room.id)} room-assignments-${actions.esc(room.id)}">${expanded ? 'Свернуть' : 'Изменить'}</button></div>`,
      `<div class="workspace-room-heading" id="room-heading-${actions.esc(room.id)}">`,
      `<label class="field">Название кабинета<span class="workspace-room-name-control"><input data-room-name value="${actions.esc(room.name)}" `,
      `maxlength="100" required ${disabled}>`,
      `<span class="workspace-room-number" data-room-number aria-hidden="true">${index + 1}</span></span></label>`,
      `<label class="telegram-switch">`,
      `<input type="checkbox" data-room-active ${room.active ? 'checked' : ''} ${disabled}> Действует</label>`,
      disabled || room.id === 'main'
        ? ''
        : '<div class="workspace-room-delete"><button type="button" class="text-btn danger" data-remove-room>Удалить</button>' +
          actions.settingsHelpHtml(
            'Удаление кабинета',
            'Удалить можно только пустой кабинет — без записей, в том числе прошлых. Если записи есть, снимите отметку «Действует»: кабинет отключится, а история сохранится. В организации должен остаться хотя бы один действующий кабинет.',
          ) +
          '</div>',
      '</div>',
      `<div class="workspace-room-assignments" id="room-assignments-${actions.esc(room.id)}" ${soleAssignedStaff ? 'hidden' : ''}><div class="field workspace-staff-mode"><div class="settings-label-row">`,
      `<label for="room-mode-${actions.esc(room.id)}">Кто здесь принимает</label>`,
      `<span class="workspace-sharing-hint" ${multiple ? '' : 'hidden'}>`,
      actions.settingsHelpHtml(
        'Несколько сотрудников в кабинете',
        'Кабинет доступен выбранным сотрудникам. Возможность одновременных записей задаётся галочкой «Запретить пересечения в этом кабинете».',
      ),
      '</span></div>',
      `<select id="room-mode-${actions.esc(room.id)}" data-room-staff-mode ${assignmentDisabled}>`,
      `<option value="single" ${multiple ? '' : 'selected'}>Один сотрудник</option>`,
      `<option value="multiple" ${multiple ? 'selected' : ''}>Несколько сотрудников</option>`,
      `</select>`,
      `</div>`,
      `<fieldset>`,
      `<legend>Выберите ${multiple ? 'сотрудников' : 'сотрудника'}</legend>`,
      `<div class="workspace-staff">${staff}</div>`,
      `</fieldset></div>`,
      '<div class="workspace-protection"><h4>Занятость кабинета</h4><div class="settings-label-row">',
      '<label class="telegram-switch"><input type="checkbox" data-room-prevent-overlap ',
      `aria-label="Запретить пересечения в кабинете ${actions.esc(room.name)}" ${room.preventOverlap !== false ? 'checked' : ''} ${overlapDisabled}></label>`,
      '<span>Запретить пересечения в этом кабинете</span>',
      actions.settingsHelpHtml(
        'Пересечения в кабинете',
        'При включённой галочке в этом кабинете может быть только один приём в каждый момент. Если снять её, разные сотрудники смогут принимать одновременно. Правила остальных кабинетов не меняются. Занятость одного сотрудника настраивается отдельно.',
      ),
      '</div></div>',
      `</article>`,
    ].join('');
  }
  function renderWorkspaceSettings() {
    const root = actions.$('#workspace-settings');
    if (!root) return;
    const w = state.workspace,
      disabled = w.canEdit ? '' : 'disabled';
    if (!actions.canManageTeam()) {
      root.innerHTML = [
        `<section class="workspace-layout-bar" data-room-layout="${w.roomLayout === 'multiple' ? 'multiple' : 'single'}"><div class="workspace-block-heading">`,
        roomIcon,
        '<h3>Доступные кабинеты</h3></div><div class="workspace-room-tags">',
        w.rooms
          .map((r) => `<span class="workspace-room-tag">${actions.esc(r.name)}</span>`)
          .join('') || '<p class="form-hint">Пока не назначены</p>',
        '</div></section>',
      ].join('');
      return;
    }
    root.innerHTML = [
      `<form id="workspace-settings-form" data-workspace-revision="${w.revision}">`,
      `<section class="workspace-layout-bar" data-room-layout="${w.roomLayout === 'multiple' ? 'multiple' : 'single'}"><div class="workspace-block-heading">`,
      roomIcon,
      '<div><h3>Кабинеты</h3><p class="form-hint">Помещения и сотрудники, которые в них принимают.</p></div></div>',
      `<label class="field workspace-layout-field">Количество кабинетов<select name="roomLayout" ${disabled}>`,
      `<option value="single" ${w.roomLayout === 'single' ? 'selected' : ''}>Один кабинет</option>`,
      `<option value="multiple" ${w.roomLayout === 'multiple' ? 'selected' : ''}>Несколько кабинетов</option>`,
      `</select>`,
      `</label></section>`,
      `<div id="workspace-room-list">${w.rooms.map((room, index) => workspaceRoomEditorHtml(room, index)).join('')}</div>${w.canEdit ? `<button type="button" class="secondary" id="workspace-add-room" ${w.roomLayout === 'multiple' ? '' : 'hidden'}>+ Добавить кабинет</button>` : ''}`,
      `<input type="checkbox" name="enabled" hidden ${w.enabled ? 'checked' : ''} ${disabled}>`,
      canAssignRooms()
        ? `<div class="workspace-settings-actions"><button type="submit" class="primary">${w.canEdit || w.canEditRoomOverlap ? 'Сохранить настройки' : 'Сохранить назначения'}</button></div>`
        : '',
      w.canEdit
        ? ''
        : '<div class="settings-label-row"><span class="form-hint">Названия, количество и отключение кабинетов — у владельца</span>' +
          actions.settingsHelpHtml(
            'Настройки кабинетов',
            'Администратор назначает сотрудников в существующие кабинеты и разрешает или запрещает пересечения в каждом из них. Названия, количество и отключение кабинетов настраивает владелец. Готовые записи сохраняются: при необходимости сначала перенесите будущие приёмы вручную.',
          ) +
          '</div>',
      '<p id="workspace-settings-message" ',
      `role="status">`,
      `</p>`,
      `</form>`,
    ].join('');
  }
  function workspaceSettingsMessage(form, text) {
    form.querySelector('#workspace-settings-message').textContent = text;
  }
  function syncWorkspaceRoomLayout(form) {
    const add = form.querySelector('#workspace-add-room');
    if (add) add.hidden = form.elements.roomLayout.value !== 'multiple';
    form.querySelector('.workspace-layout-bar').dataset.roomLayout = form.elements.roomLayout.value;
  }
  function expandWorkspaceRoom(row, expanded) {
    row.dataset.roomExpanded = String(expanded);
    const button = row.querySelector('[data-room-edit]');
    button.setAttribute('aria-expanded', String(expanded));
    button.textContent = expanded ? 'Свернуть' : 'Изменить';
  }
  function syncWorkspaceRoomSummary(row) {
    if (!row) return;
    row.querySelector('[data-room-summary-name]').textContent =
      row.querySelector('[data-room-name]').value || 'Название не заполнено';
    const names = [...row.querySelectorAll('[data-room-staff]:checked')]
      .map((input) => input.closest('label').querySelector('strong').textContent)
      .join(', ');
    row.querySelector('[data-room-summary-staff]').textContent =
      (names || 'Сотрудники не назначены') +
      (row.querySelector('[data-room-active]').checked ? '' : ' · Не действует');
  }
  function renderWorkspaceError(text) {
    const root = actions.$('#workspace-settings');
    if (root) root.innerHTML = '<p class="error">' + actions.esc(text) + '</p>';
  }
  return {
    workspaceSettingsHtml,
    workspaceRoomEditorHtml,
    renderWorkspaceSettings,
    workspaceSettingsMessage,
    syncWorkspaceRoomLayout,
    expandWorkspaceRoom,
    syncWorkspaceRoomSummary,
    renderWorkspaceError,
  };
}

function createWorkspaceSettings(state, actions) {
  const canAssignRooms = () => state.workspace.canEdit || state.workspace.canEditRoomAssignments;
  function bindWorkspaceSettingsEvents() {
    document.addEventListener(
      'invalid',
      (e) => {
        const row = e.target.closest('#workspace-settings-form [data-room-id]');
        if (row) actions.expandWorkspaceRoom(row, true);
      },
      true,
    );
    document.addEventListener('input', (e) => {
      actions.syncWorkspaceRoomSummary(e.target.closest('#workspace-settings-form [data-room-id]'));
    });
    document.addEventListener('click', (e) => {
      if (state.busy) return;
      const edit = e.target.closest('#workspace-settings-form [data-room-edit]');
      if (edit) {
        const row = edit.closest('[data-room-id]'),
          name = row.querySelector('[data-room-name]'),
          expanded = row.dataset.roomExpanded !== 'true';
        if (!expanded && !name.checkValidity()) {
          name.reportValidity();
          return;
        }
        actions.expandWorkspaceRoom(row, expanded);
        return;
      }
      if (!state.workspace.canEdit) return;
      if (e.target.closest('#workspace-add-room')) {
        const form = actions.$('#workspace-settings-form'),
          list = form?.querySelector('#workspace-room-list');
        if (!list || list.children.length >= 50 || form.elements.roomLayout.value !== 'multiple')
          return;
        const room = {
          id: 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
          name: 'Кабинет ' + (list.children.length + 1),
          active: true,
          preventOverlap: true,
          staffMode: 'single',
          staffIds: [actions.accountId()],
        };
        list.insertAdjacentHTML(
          'beforeend',
          actions.workspaceRoomEditorHtml(room, list.children.length, true),
        );
        actions.workspaceSettingsMessage(form, '');
        return;
      }
      const remove = e.target.closest('[data-remove-room]');
      if (!remove) return;
      const row = remove.closest('[data-room-id]'),
        form = row.closest('form');
      if (row.dataset.roomId === 'main') return;
      if (
        row.querySelector('[data-room-active]').checked &&
        form.querySelectorAll('[data-room-active]:checked').length === 1
      ) {
        actions.workspaceSettingsMessage(form, 'Нужно оставить хотя бы один действующий кабинет.');
        return;
      }
      if (
        window.confirm(
          'Удалить кабинет? Удалить можно только кабинет без записей, в том числе прошлых. Изменение применится после сохранения настроек.',
        )
      ) {
        row.remove();
        form.querySelectorAll('[data-room-number]').forEach((number, index) => {
          number.textContent = String(index + 1);
        });
      }
    });
    document.addEventListener('change', (e) => {
      const form = e.target.closest('#workspace-settings-form');
      if (!form || state.busy || !canAssignRooms()) return;
      if (
        !state.workspace.canEdit &&
        !e.target.matches('[data-room-staff], [data-room-staff-mode]') &&
        !(state.workspace.canEditRoomOverlap && e.target.matches('[data-room-prevent-overlap]'))
      )
        return;
      actions.workspaceSettingsMessage(form, '');
      if (e.target.name === 'roomLayout') {
        if (
          e.target.value === 'single' &&
          form.querySelectorAll('[data-room-active]:checked').length !== 1
        ) {
          e.target.value = 'multiple';
          actions.workspaceSettingsMessage(
            form,
            'Сначала оставьте один действующий кабинет: отключите остальные отметкой «Действует». История сохранится.',
          );
        }
        actions.syncWorkspaceRoomLayout(form);
        return;
      }
      if (e.target.matches('[data-room-active]')) {
        if (!form.querySelector('[data-room-active]:checked')) {
          e.target.checked = true;
          actions.workspaceSettingsMessage(
            form,
            'Нужно оставить хотя бы один действующий кабинет.',
          );
        }
        if (form.querySelectorAll('[data-room-active]:checked').length > 1) {
          form.elements.roomLayout.value = 'multiple';
          actions.syncWorkspaceRoomLayout(form);
        }
        actions.syncWorkspaceRoomSummary(e.target.closest('[data-room-id]'));
        return;
      }
      if (!e.target.matches('[data-room-staff-mode]')) return;
      const row = e.target.closest('[data-room-id]'),
        multiple = e.target.value === 'multiple';
      if (!multiple && row.querySelectorAll('[data-room-staff]:checked').length > 1) {
        e.target.value = 'multiple';
        actions.workspaceSettingsMessage(
          form,
          'Сначала оставьте выбранным одного сотрудника. Назначения не удалены.',
        );
        return;
      }
      for (const input of row.querySelectorAll('[data-room-staff]'))
        input.type = multiple ? 'checkbox' : 'radio';
      row.querySelector('legend').textContent = multiple
        ? 'Выберите сотрудников'
        : 'Выберите сотрудника';
      row.querySelector('.workspace-sharing-hint').hidden = !multiple;
    });
    document.addEventListener('submit', async (e) => {
      if (e.target.id !== 'workspace-settings-form') return;
      e.preventDefault();
      if (state.busy || !canAssignRooms()) return;
      const form = e.target,
        values = actions.workspaceFormValues(form),
        button = form.querySelector('[type="submit"]');
      actions.workspaceSettingsMessage(form, '');
      const rulesChanged =
        (state.workspace.canEdit && values.enabled !== state.workspace.enabled) ||
        ((state.workspace.canEdit || state.workspace.canEditRoomOverlap) &&
          (values.rooms || values.roomAssignments || []).some((room) => {
            const prior = state.workspace.rooms.find((r) => r.id === room.id);
            return (
              prior &&
              typeof room.preventOverlap === 'boolean' &&
              prior.preventOverlap !== room.preventOverlap
            );
          }));
      if (
        rulesChanged &&
        !window.confirm(
          'Изменить правила пересечений? Прежние записи сохранятся. При включении защиты сервер проверит будущие записи по новым правилам.',
        )
      )
        return;
      state.busy = true;
      button.disabled = true;
      try {
        await actions.saveWorkspaceSettings(values);
      } catch (error) {
        actions.workspaceSettingsMessage(form, error.message);
      } finally {
        state.busy = false;
        if (button.isConnected) button.disabled = false;
      }
    });
  }
  return { bindWorkspaceSettingsEvents };
}

function createTeamMemberView(state, actions) {
  function channelsHtml(member) {
    return (
      '<div class="team-member-channels" aria-label="Личные уведомления">' +
      ['max', 'telegram', 'push']
        .map((channel) => {
          const name = { max: 'MAX', telegram: 'Telegram', push: 'Push' }[channel];
          const status = member.notifications?.[channel];
          const enabled = status?.linked && status?.enabled;
          const description = !status
            ? 'Статус неизвестен'
            : !status.prepared
              ? 'Пока недоступны'
              : !status.linked
                ? 'Не подключены'
                : enabled
                  ? 'Личное подключение включено'
                  : 'Подключены, уведомления выключены';
          const title = `${name}: ${description}. Сотрудник настраивает подключение в своём аккаунте.`;
          return `<span class="connection-service connection-${channel} team-channel ${enabled ? 'is-linked' : ''}" role="img" tabindex="0" title="${actions.esc(title)}" aria-label="${actions.esc(title)}">${actions.staffChannelIconHtml(channel)}</span>`;
        })
        .join('') +
      '</div>'
    );
  }
  function memberHtml(member) {
    const esc = actions.esc,
      id = esc(member.accountId);
    const role = state.roleNames[member.role] || member.role;
    const name =
      member.displayName === role ? 'Имя не заполнено' : member.displayName || 'Без имени';
    const canEdit = actions.canManageMembers() && member.role !== 'owner';
    const specialist = ['owner', 'cosmetologist'].includes(member.role);
    const status = member.status === 'active' ? 'Доступ включён' : 'Доступ выключен';
    const access = canEdit
      ? `<button type="button" class="secondary member-access-toggle team-access-pill" role="switch" aria-checked="${member.status === 'active'}" aria-label="Доступ к сайту: ${esc(name)}" data-member-status="${id}" data-next-status="${member.status === 'active' ? 'suspended' : 'active'}">${status}</button>`
      : `<span class="team-access-pill" aria-label="${esc(name)}: ${status}">${status}</span>`;
    const roleControl = canEdit
      ? [
          '<details class="member-menu-action"><summary>Изменить роль</summary>',
          `<label class="field member-role-field">Роль<select aria-label="Роль ${esc(name)}" data-member-role="${id}">`,
          `<option value="salon_admin" ${member.role === 'salon_admin' ? 'selected' : ''}>Администратор</option>`,
          `<option value="cosmetologist" ${member.role === 'cosmetologist' ? 'selected' : ''}>Сотрудник</option></select></label></details>`,
          '<details class="member-menu-action"><summary>Изменить специальность</summary>',
          `<form class="member-specialty-form" data-member-specialty="${id}"><label class="field">Специальность<input name="specialty" maxlength="120" value="${esc(member.specialty || '')}" placeholder="Необязательно"></label><button class="secondary" type="submit">Сохранить</button></form></details>`,
        ].join('')
      : '';
    const ruleControl = specialist
      ? `<details class="member-menu-action"><summary>Правила записи</summary><div data-team-rule-staff="${id}"></div></details>`
      : '';
    const menu =
      canEdit || specialist
        ? `<details class="member-edit-panel team-member-menu" name="team-member-menu"><summary title="Действия сотрудника" aria-label="Действия сотрудника: ${esc(name)}"><span aria-hidden="true">⋯</span></summary><div class="member-menu-body">${roleControl}${ruleControl}</div></details>`
        : '<button type="button" class="team-more-placeholder" disabled aria-label="Действия сотрудника недоступны"><span aria-hidden="true">⋯</span></button>';
    return `<article class="team-member ${member.status !== 'active' ? 'is-suspended' : ''}" data-member="${id}"><div class="team-member-main"><span class="team-avatar" aria-hidden="true">${esc(actions.initials(name))}</span><div class="team-member-copy"><strong>${esc(name)}</strong><small>${esc(role)}${specialist && member.specialty ? ' · ' + esc(member.specialty) : ''}</small></div></div><div class="team-member-actions">${channelsHtml(member)}${access}${menu}</div></article>`;
  }
  return { memberHtml };
}

function createPaidServicesView(state, actions) {
  const money = (kopecks) =>
    Number.isSafeInteger(kopecks)
      ? (BigInt(kopecks) / 100n).toLocaleString('ru-RU') +
        ',' +
        (BigInt(kopecks) % 100n).toString().padStart(2, '0') +
        ' ₽'
      : '—';
  const date = (value) => {
    const parsed = new Date(value);
    return value && Number.isFinite(parsed.getTime()) ? parsed.toLocaleDateString('ru-RU') : '—';
  };
  const terminal = (payment) => ['succeeded', 'canceled', 'rejected'].includes(payment?.status);
  function paymentMessage(payment) {
    if (payment.status === 'succeeded')
      return 'Оплата подтверждена. Состояние пакета показано выше.';
    if (payment.notice) return payment.notice;
    return (
      {
        canceled: 'Оплата отменена. Пакет не подключён.',
        rejected: 'Заказ не создан. Проверьте условия и повторите оплату.',
        review: 'Заказ требует сверки администратором. Не создавайте другую оплату.',
        uncertain: 'Результат создания оплаты уточняется. Проверяйте прежний заказ.',
        creating: 'Оплата создаётся. Не создавайте другой заказ.',
        pending: 'Ожидаем подтверждения оплаты. Доступ появится после подтверждения.',
      }[payment.status] || 'Статус заказа уточняется. Обновите результат этой оплаты.'
    );
  }
  function subscriptionHtml(subscription) {
    if (!subscription?.active)
      return '<section class="paid-package-current"><h4>Активного пакета пока нет</h4><p>Выберите пакет для подключения этой услуги.</p></section>';
    return (
      '<section class="paid-package-current"><div class="paid-service-heading"><h4>' +
      actions.esc(subscription.title) +
      '</h4><span class="paid-service-status" data-enabled="true">' +
      (subscription.source === 'trial'
        ? 'Пробный пакет'
        : subscription.testMode
          ? 'Тестовая оплата'
          : 'Оплачен') +
      '</span></div><p>С ' +
      actions.esc(date(subscription.startsAt)) +
      ' до ' +
      actions.esc(date(subscription.endsAt)) +
      '</p><dl class="paid-package-quota">' +
      (subscription.quotaUnit === 'access'
        ? []
        : [
            [
              subscription.quotaUnit === 'units' ? 'Осталось единиц' : 'Осталось задач',
              subscription.remainingTasks,
            ],
            ['Использовано', subscription.usedTasks],
            ['Выполняется', subscription.reservedTasks],
          ]
      )
        .map(
          ([label, value]) =>
            '<div><dt>' + label + '</dt><dd>' + actions.esc(value) + '</dd></div>',
        )
        .join('') +
      '</dl></section>'
    );
  }
  function checkoutForm(data, packages, blocked = false, service = 'voice-assistant') {
    if (actions.accountRole() !== 'owner')
      return '<p class="form-hint">Покупкой и продлением пакета управляет владелец организации.</p>';
    if (!packages.length) return '';
    return (
      '<form class="paid-package-checkout" data-paid-checkout data-service-code="' +
      actions.esc(service) +
      '"><fieldset' +
      (!data.paymentReady || !data.available || data.subscription?.active || blocked
        ? ' disabled'
        : '') +
      '><legend>Купить пакет</legend><label class="field">Пакет<select name="packageId">' +
      packages
        .map(
          (item) =>
            '<option value="' +
            actions.esc(item.id) +
            '">' +
            actions.esc(item.title + ' · ' + money(item.priceKopecks)) +
            '</option>',
        )
        .join('') +
      '</select></label><label class="field">Почта для чека<input name="receiptEmail" ' +
      'type="email" required maxlength="254" autocomplete="email" value="' +
      actions.esc(state.account?.email || '') +
      '"></label><label class="paid-package-consent"><input type="checkbox" name="acceptTerms" ' +
      'required> Я ознакомился с условиями пакета и согласен с оплатой.</label></fieldset>' +
      '<button class="primary" type="submit"' +
      (!data.paymentReady || !data.available || data.subscription?.active || blocked
        ? ' disabled'
        : '') +
      '>' +
      (data.subscription?.active
        ? 'Пакет уже действует'
        : blocked
          ? 'Проверьте результат прежнего заказа'
          : 'Перейти к оплате') +
      '</button></form>'
    );
  }
  function paidServicesContentHtml(data, selectedPayment, pendingServices) {
    const packages = (data.packages || []).filter((item) => item.enabled);
    const services = data.services || [
      { code: 'voice-assistant', title: 'Голосовой помощник', subscription: data.subscription },
    ];
    const orders = data.orders || [];
    return (
      '<div class="paid-services">' +
      services
        .map((service) => {
          const subscription = service.subscription,
            offers = packages.filter(
              (item) => (item.serviceCode || 'voice-assistant') === service.code,
            );
          const payment =
            (selectedPayment?.package?.serviceCode || 'voice-assistant') === service.code &&
            selectedPayment
              ? selectedPayment
              : orders.find(
                  (item) =>
                    (item.package?.serviceCode || 'voice-assistant') === service.code &&
                    !terminal(item),
                );
          const operation = pendingServices.get(service.code);
          return (
            '<section class="paid-service-group" data-paid-service="' +
            actions.esc(service.code) +
            '"><h3>' +
            actions.esc(service.title) +
            '</h3>' +
            subscriptionHtml(subscription) +
            (subscription?.active
              ? '<button type="button" class="secondary" data-paid-toggle="' +
                actions.esc(service.code) +
                '" data-revision="' +
                actions.esc(subscription.connectionRevision || 0) +
                '" data-enabled="' +
                Boolean(subscription.enabled) +
                '">' +
                (subscription.enabled ? 'Приостановить услугу' : 'Возобновить услугу') +
                '</button>'
              : '') +
            '<div class="paid-package-catalog">' +
            offers
              .map(
                (item) =>
                  '<article class="paid-service"><h4>' +
                  actions.esc(item.title) +
                  '</h4><p class="paid-package-price">' +
                  actions.esc(money(item.priceKopecks)) +
                  '</p><p>' +
                  actions.esc(item.periodMonths || 1) +
                  ' мес. · ' +
                  (item.quotaUnit === 'access'
                    ? 'Доступ на срок'
                    : actions.esc(item.taskLimit) +
                      ' ' +
                      (item.quotaUnit === 'units' ? 'единиц' : 'задач')) +
                  '</p></article>',
              )
              .join('') +
            '</div>' +
            (payment && !terminal(payment)
              ? '<p>' +
                actions.esc(paymentMessage(payment)) +
                '</p><button type="button" class="secondary" data-paid-check-order="' +
                actions.esc(payment.checkoutId || payment.id) +
                '">Проверить прежний заказ</button>'
              : '') +
            checkoutForm(
              { ...data, subscription },
              offers,
              Boolean((payment && !terminal(payment)) || operation),
              service.code,
            ) +
            '</section>'
          );
        })
        .join('') +
      (!packages.length ? '<p>Пакеты пока не опубликованы.</p>' : '') +
      '<section class="paid-package-rules"><h4>Как работает оплата</h4><p>Каждая услуга имеет свой срок и лимит. Остаток не переносится. Продление — новой оплатой, без автоматического списания. Уточнения внутри одной задачи помощника бесплатны.</p></section>' +
      (!data.paymentReady
        ? '<p class="paid-package-notice">Приём оплат ещё не подключён.</p>'
        : '') +
      (data.paymentNotice
        ? '<p class="form-hint">' + actions.esc(data.paymentNotice) + '</p>'
        : '') +
      '<p class="form-hint">Данные карты вводятся только на защищённой странице ЮKassa. Картотека их не получает. Почта используется для чека.</p>' +
      (orders.length
        ? '<details><summary>История покупок</summary><ul>' +
          orders
            .map(
              (order) =>
                '<li>' +
                actions.esc(
                  date(order.createdAt) +
                    ' · ' +
                    order.package.title +
                    ' · ' +
                    money(order.package.priceKopecks),
                ) +
                '<p>' +
                actions.esc(paymentMessage(order)) +
                '</p><p>' +
                actions.esc(
                  'Чек: ' +
                    ({
                      succeeded: 'зарегистрирован',
                      pending: 'в обработке',
                      canceled: 'ошибка регистрации',
                    }[order.receiptRegistration] || 'статус уточняется'),
                ) +
                (order.refund?.knownRefundedKopecks
                  ? ' · Возвращено: ' + actions.esc(money(order.refund.knownRefundedKopecks))
                  : '') +
                '</p><button type="button" class="text-btn" data-paid-check-order="' +
                actions.esc(order.checkoutId || order.id) +
                '">Проверить оплату и чек</button></li>',
            )
            .join('') +
          '</ul></details>'
        : '') +
      '<p role="status" aria-live="polite" data-paid-message></p><button type="button" class="secondary" data-paid-refresh>Обновить пакеты и статус оплаты</button></div>'
    );
  }
  return { paidServicesContentHtml, paidPaymentMessage: paymentMessage, paidPriceText: money };
}

function createPaidServices(state, actions) {
  const entries = new WeakMap(),
    operations = new Map(),
    selector = '#paid-services-settings';
  let bound = false;
  const identity = () =>
    JSON.stringify([state.account?.id, state.account?.organizationId, state.account?.role]);
  const operationKey = (entry, service = 'voice-assistant') => entry.identity + '\u0000' + service;
  const terminal = (payment) => ['succeeded', 'canceled', 'rejected'].includes(payment?.status);
  function finishKnownOperation(entry, payment) {
    const returnedId = payment?.checkoutId || payment?.id;
    if (!terminal(payment) || !returnedId) return;
    for (const [key, operation] of operations)
      if (
        key.startsWith(entry.identity + '\u0000') &&
        (operation.result?.checkoutId || operation.result?.id) === returnedId
      )
        operations.delete(key);
  }
  function paidServicesSettingsHtml() {
    if (!state.multiUser || actions.accountRole() !== 'owner') return '';
    return actions.settingsSectionHtml(
      'Пакеты и оплата',
      'paid-services-settings',
      '<div class="paid-services"><p>Услуги, подключённые к вашей организации.</p><p role="status" data-paid-message>Откройте раздел, чтобы посмотреть пакет и доступные задачи.</p><button type="button" class="secondary" data-paid-refresh>Обновить</button></div>',
    );
  }
  function entryFor(root) {
    let entry = entries.get(root);
    if (!entry || entry.account !== state.account || entry.identity !== identity()) {
      entry?.controller?.abort();
      entry = { account: state.account, identity: identity(), generation: 0, snapshot: null };
      entries.set(root, entry);
    }
    return entry;
  }
  function current(root, entry) {
    return (
      root.isConnected &&
      actions.$(selector) === root &&
      state.account === entry.account &&
      identity() === entry.identity &&
      state.sessionReady !== false
    );
  }
  function visible(root, entry) {
    return (
      current(root, entry) &&
      state.currentView === 'settings' &&
      !document.hidden &&
      !root.closest('[hidden], details:not([open])')
    );
  }
  function message(root, text, error = false) {
    const node = root.querySelector('[data-paid-message]');
    if (!node) return;
    node.textContent = text;
    node.dataset.status = error ? 'error' : '';
  }
  function render(root, entry) {
    const pendingServices = new Map();
    for (const service of entry.snapshot.services || [{ code: 'voice-assistant' }])
      pendingServices.set(service.code, operations.get(operationKey(entry, service.code)));
    root.innerHTML = actions.paidServicesContentHtml(
      entry.snapshot,
      entry.payment,
      pendingServices,
    );
    for (const form of root.querySelectorAll('[data-paid-checkout]')) {
      const operation = operations.get(operationKey(entry, form.dataset.serviceCode));
      if (!operation) continue;
      form.elements.packageId.value = operation.body.packageId;
      form.elements.receiptEmail.value = operation.body.receiptEmail;
      form.elements.acceptTerms.checked = true;
      form.querySelector('fieldset').disabled = true;
      const button = form.querySelector('[type="submit"]');
      button.disabled = false;
      button.textContent =
        operation.result?.status === 'pending' && operation.result.confirmationUrl
          ? 'Продолжить оплату'
          : 'Проверить прежний заказ';
      message(root, 'Незавершённый запрос оплаты. Повтор сохранит прежний номер операции.', true);
    }
  }
  async function load(root, selectedCheckoutId = null) {
    const entry = entryFor(root);
    if (!visible(root, entry) || entry.busy) return;
    entry.controller?.abort();
    const controller = new AbortController(),
      generation = ++entry.generation,
      checkoutId =
        selectedCheckoutId ||
        new URLSearchParams(location.search).get('checkoutId') ||
        new URLSearchParams(location.search).get('payment') ||
        [...operations].find(([key]) => key.startsWith(entry.identity + '\u0000'))?.[1]?.result
          ?.checkoutId;
    entry.controller = controller;
    root.setAttribute('aria-busy', 'true');
    message(root, 'Загружаем пакет…');
    try {
      let payment = null;
      if (checkoutId && /^[a-f0-9-]{36}$/i.test(checkoutId))
        payment = await actions.request(
          '/api/billing/payment?id=' + encodeURIComponent(checkoutId),
          {
            signal: controller.signal,
          },
        );
      if (!visible(root, entry) || generation !== entry.generation) return;
      const data = await actions.request('/api/billing', { signal: controller.signal });
      if (!visible(root, entry) || generation !== entry.generation) return;
      entry.snapshot = data;
      entry.payment = payment;
      finishKnownOperation(entry, payment);
      render(root, entry);
      if (
        payment?.status === 'succeeded' &&
        (payment.package?.serviceCode || 'voice-assistant') === 'voice-assistant'
      ) {
        message(root, 'Оплата подтверждена. Состояние пакета показано выше.');
        const scope = await actions
          .request('/api/assistant/scope', {
            signal: controller.signal,
            assistantRequest: true,
          })
          .catch(() => null);
        if (scope && current(root, entry) && generation === entry.generation)
          actions.applyAssistantScope(scope);
      } else if (payment)
        message(
          root,
          actions.paidPaymentMessage(payment),
          ['review', 'rejected', 'uncertain'].includes(payment.status),
        );
    } catch (error) {
      if (visible(root, entry) && generation === entry.generation && !controller.signal.aborted)
        message(root, error.message, true);
    } finally {
      if (current(root, entry) && generation === entry.generation) {
        root.removeAttribute('aria-busy');
        entry.controller = null;
      }
    }
  }
  async function checkout(root, form) {
    const entry = entryFor(root);
    if (!visible(root, entry) || entry.busy || actions.accountRole() !== 'owner') return;
    const service = form.dataset.serviceCode || 'voice-assistant',
      key = operationKey(entry, service);
    let operation = operations.get(key);
    if (!operation) {
      if (
        entry.payment &&
        !terminal(entry.payment) &&
        (entry.payment.package?.serviceCode || 'voice-assistant') === service
      )
        return;
      if (!entry.snapshot?.paymentReady || !entry.snapshot.available || !form.reportValidity())
        return;
      const values = new FormData(form),
        selected = entry.snapshot.packages.find((item) => item.id === values.get('packageId'));
      if (!selected?.enabled) return;
      operation = {
        body: {
          packageId: selected.id,
          packageVersion: selected.version,
          requestId: window.crypto.randomUUID(),
          receiptEmail: String(values.get('receiptEmail')).trim(),
          acceptedTermsVersion: entry.snapshot.termsVersion,
        },
      };
      entry.busy = true;
      const confirmed = await actions.confirmAction(
        'Перейти к оплате пакета?',
        selected.title +
          ': ' +
          actions.paidPriceText(selected.priceKopecks) +
          ' на ' +
          (selected.periodMonths || 1) +
          ' мес., ' +
          (selected.quotaUnit === 'access' ? 'доступ на срок' : selected.taskLimit + ' единиц') +
          '. Автоматического продления нет.',
        'Перейти к оплате',
      );
      entry.busy = false;
      if (!confirmed || !visible(root, entry)) return;
      operations.set(key, operation);
    }
    entry.controller?.abort();
    entry.generation++;
    entry.busy = true;
    render(root, entry);
    form = [...root.querySelectorAll('[data-paid-checkout]')].find(
      (item) => (item.dataset.serviceCode || 'voice-assistant') === service,
    );
    const button = form.querySelector('[type="submit"]');
    button.disabled = true;
    message(root, 'Готовим оплату…');
    try {
      operation.result = await actions.request('/api/billing/checkout', {
        method: 'POST',
        body: JSON.stringify(operation.body),
      });
      if (!visible(root, entry)) return;
      if (terminal(operation.result)) {
        finishKnownOperation(entry, operation.result);
        entry.busy = false;
        await load(root);
        if (operation.result.status === 'succeeded' && service === 'voice-assistant') {
          const scope = await actions
            .request('/api/assistant/scope', {
              assistantRequest: true,
            })
            .catch(() => null);
          if (scope && current(root, entry)) actions.applyAssistantScope(scope);
        }
        if (visible(root, entry))
          message(
            root,
            actions.paidPaymentMessage(operation.result),
            operation.result.status === 'rejected',
          );
        return;
      }
      if (operation.result.status !== 'pending' || !operation.result.confirmationUrl) {
        render(root, entry);
        message(
          root,
          actions.paidPaymentMessage(operation.result),
          ['review', 'uncertain'].includes(operation.result.status),
        );
        return;
      }
      const confirmation = new URL(operation.result.confirmationUrl);
      if (
        confirmation.protocol !== 'https:' ||
        confirmation.username ||
        confirmation.password ||
        confirmation.hostname !== 'yoomoney.ru' ||
        confirmation.port ||
        confirmation.hash ||
        !(
          confirmation.pathname.startsWith('/checkout/payments/') ||
          confirmation.pathname === '/api-pages/v2/payment-confirm/epl'
        )
      )
        throw Error('Не удалось получить защищённую ссылку оплаты. Обновите статус пакета.');
      actions.toast('Открываем страницу оплаты.');
      location.assign(confirmation.href);
    } catch (error) {
      if (error.outcomeUnknown) operation.uncertain = true;
      if (!error.outcomeUnknown && !operation.result && !operation.uncertain)
        operations.delete(key);
      if (current(root, entry)) {
        render(root, entry);
        message(
          root,
          error.outcomeUnknown
            ? 'Ответ не получен. Повторите прежний запрос, чтобы избежать повторного платежа.'
            : operation.uncertain
              ? error.message + ' Результат прежнего заказа пока неизвестен. Проверяйте только его.'
              : error.message,
          true,
        );
      }
    } finally {
      entry.busy = false;
      if (button.isConnected) button.disabled = false;
      if (current(root, entry)) root.removeAttribute('aria-busy');
    }
  }
  async function toggleService(root, button) {
    const entry = entryFor(root),
      code = button.dataset.paidToggle;
    if (!visible(root, entry) || entry.busy || actions.accountRole() !== 'owner') return;
    entry.connectionOperations ||= new Map();
    let operation = entry.connectionOperations.get(code);
    if (!operation) {
      operation = {
        serviceCode: code,
        enabled: button.dataset.enabled !== 'true',
        expectedRevision: Number(button.dataset.revision),
        requestId: window.crypto.randomUUID(),
      };
      entry.connectionOperations.set(code, operation);
    }
    entry.busy = true;
    button.disabled = true;
    try {
      const data = await actions.request('/api/billing/services/connection', {
        method: 'POST',
        body: JSON.stringify(operation),
      });
      if (!current(root, entry)) return;
      entry.connectionOperations.delete(code);
      entry.snapshot = data;
      render(root, entry);
      message(
        root,
        operation.enabled
          ? 'Услуга возобновлена.'
          : 'Услуга приостановлена. Другие подключения сохранены.',
      );
      if (code === 'voice-assistant') {
        const scope = await actions
          .request('/api/assistant/scope', { assistantRequest: true })
          .catch(() => null);
        if (scope && current(root, entry)) actions.applyAssistantScope(scope);
      }
    } catch (error) {
      if (!error.unknown && !error.outcomeUnknown) entry.connectionOperations.delete(code);
      if (current(root, entry)) message(root, error.message, true);
    } finally {
      entry.busy = false;
      if (button.isConnected) button.disabled = false;
    }
  }
  function bindPaidServicesEvents() {
    if (bound) return;
    bound = true;
    document.addEventListener(
      'toggle',
      (event) => {
        const root = event.target.querySelector?.(selector);
        if (!root || !event.target.matches('details.settings-tile')) return;
        if (event.target.open) void load(root);
        else entryFor(root).controller?.abort();
      },
      true,
    );
    document.addEventListener('click', (event) => {
      const root = event.target.closest?.(selector);
      if (root && event.target.closest('[data-paid-refresh]')) void load(root);
      const order = event.target.closest?.('[data-paid-check-order]');
      if (root && order) void load(root, order.dataset.paidCheckOrder);
      const toggle = event.target.closest?.('[data-paid-toggle]');
      if (root && toggle) void toggleService(root, toggle);
    });
    document.addEventListener('submit', (event) => {
      const form = event.target.closest?.('[data-paid-checkout]');
      if (!form) return;
      event.preventDefault();
      void checkout(form.closest(selector), form);
    });
    const cancel = () => {
      const root = actions.$(selector);
      if (root) entryFor(root).controller?.abort();
    };
    window.addEventListener('pagehide', cancel);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) cancel();
    });
  }
  return { paidServicesSettingsHtml, bindPaidServicesEvents };
}

