            busy = false;
            updateControls();
            const active = document.activeElement;
            if (
              restoreFocus &&
              current() &&
              (active === document.body || active === toggle || !active?.isConnected)
            )
              root.querySelector('[data-calendar-switch]')?.focus({ preventScroll: true });
